s=\"gyx-card\"><b>第 ${h.i + 1} 条线索</b><div class=\"gyx-tip\">${X.v('线索藏在', '去找找', '它在')}：<b>${placeOf(h.steps[h.i].place)}</b></div>${h.steps[h.i].place === 'chat' || h.steps[h.i].place === 'notify' ? '' : ''}</div>\n        <div class=\"gyx-row\"><input id=\"gyxHtIn\" class=\"gyx-in\" style=\"flex:1\" placeholder=\"找到线索了？答案是……\" onkeydown=\"if(event.key==='Enter')gyxHuntTry()\"><button class=\"gyx-btn\" onclick=\"gyxHuntTry()\">就是它</button></div><div id=\"gyxHtMsg\" class=\"gyx-tip\"></div>\n        <div class=\"gyx-row\"><span class=\"gyx-chip\" onclick=\"gyxHuntGiveUp()\">不玩了</span></div>`\n        : `<div class=\"gyx-row\">${X.whoSel(cid, 'gyxHuntOpen')}</div><div class=\"gyx-tip\">${X.v('让 TA 偷偷给你布置一场寻宝吧。', 'TA 会把线索藏在各个地方。', '准备好了吗？')}</div><button class=\"gyx-btn\" onclick=\"this.disabled=true;this.textContent='TA 在藏线索…';gyxHuntStart('${cid}')\">开始寻宝</button>\n        <div style=\"font-weight:700;margin:12px 0 4px\">找到过的宝藏</div>${D.log.filter(x => x.cid === cid).map(x => `<div class=\"gyx-card\"><b>🎁 ${X.esc(x.prize)}</b><div class=\"gyx-tip\">${new Date(x.end).toLocaleDateString()} · ${x.n} 关 · 猜了 ${x.tries} 次</div><div class=\"gyx-hand\">${X.esc(x.letter)}</div></div>`).join('') || '<div class=\"gyx-tip\">还没有</div>'}`);\n};\nX.ctx(id => { const h = D.on; if (h && h.cid === String(id)) return `【你给她布置的寻宝正在进行】她到了第 ${h.i + 1}/${h.steps.length} 关，这关线索是「${h.steps[h.i].q}」（答案：${h.steps[h.i].a[0]}，别直接告诉她，可以逗她、给一点点提示）。`; return ''; }, 'gyxHunt');\nX.action({ key: 'gyx_hunt', label: '偷偷给她布置一场寻宝', hint: '线索藏在各处', need: c => !D.on && !D.log.some(x => x.cid === String(c.id) && Date.now() - x.end < 7 * 864e5),\n    run: async c => { D.on = await plan(c); await S.set('d', D); drop(D.on); X.notify(c, `🗺️ ${X.esc(X.name(c))} ${X.v('给你布置了一场寻宝', '偷偷藏了些线索', '在各处藏了线索')}`, '去「寻宝」看看第一条线索在哪', () => window.gyxHuntOpen()); return '布置了一场寻宝'; } }, 'gyxHunt');\nX.today(() => { const h = D.on; if (!h) return null; const s = h.steps[h.i]; return { title: '🗺️ 寻宝', rows: [s.place === 'today' ? { t: `线索 ${h.i + 1}`, x: X.esc(s.q), go: 'gyxHuntOpen()' } : { t: `第 ${h.i + 1} 关`, x: '线索在' + placeOf(s.place), go: 'gyxHuntOpen()' }] }; }, 'gyxHunt');\nX.widget('gyxHuntW', { n: '寻宝', sizes: ['s', 'm'], tap: () => window.gyxHuntOpen(), r: w => { const h = D.on; if (!h) return X.gw(w, '🗺️', '寻宝', ['找到 ' + D.log.length + ' 次宝藏']); const s = h.steps[h.i]; return X.gw(w, '🗺️', `寻宝 ${h.i + 1}/${h.steps.length}`, s.place === 'widget' ? ['线索：', X.esc(s.q)] : ['线索不在这儿', '在' + placeOf(s.place)]); } }, 'gyxHunt');\nX.memArr({ k: 'gyxHunt', ico: '🗺️', n: '寻宝', d: '找到过的宝藏和 TA 的信', arr: () => D.log, field: 'letter', text: x => x.prize + '：' + x.letter, edit: (x, v) => { const i = v.indexOf('：'); if (i > 0) { x.prize = v.slice(0, i); x.letter = v.slice(i + 1); } else x.letter = v; }, meta: x => new Date(x.end).toLocaleDateString() + ' · ' + x.n + ' 关', save: () => S.set('d', D) }, 'gyxHunt');\nX.css('gyxHtCss', `.ht-map{display:flex;align-items:center;gap:4px;margin:8px 0 12px}.ht-map span{width:30px;height:30px;border-radius:50%;background:#eee;display:flex;align-items:center;justify-content:center;font-size:13px;flex:none}.ht-map span.ok{background:#7bd3a8;color:#fff}.ht-map span.cur{background:#ffcf6b;animation:htp 1.2s infinite}.ht-map i{flex:1;border-top:2px dashed #ddd}@keyframes htp{50%{transform:scale(1.12)}}.ht-end{text-align:center}.ht-chest{font-size:80px;animation:htc 1s ease}@keyframes htc{from{transform:scale(.3) rotate(-20deg);opacity:0}}.ht-end>b{display:block;font-size:18px;margin:8px 0}`);\nX.mini({ id: 'gyxHunt', icon: '🗺️', title: 'TA 布置的寻宝', desc: '线索藏在各处，一关关解开拿礼物', cat: '一起做', onOpen: () => window.gyxHuntOpen() });\n(async () => { D = Object.assign(D, await S.get('d', {})); D.log = D.log || []; })();\n\n// 🎮 放进聊天里的游戏列表（和五子棋、UNO、猜拳在一起）；小功能里就不单独占一格了（js/79 看到这里登记了会藏起来）\n(function () {\n    const reg = () => { if (typeof registerMiniGame !== 'function') return false; registerMiniGame({ id: 'gyxHunt', name: 'TA 布置的寻宝', icon: '🗺️', getStatus: () => null, onResume: () => window.gyxHuntOpen(), onStart: (sid, opp) => window.gyxHuntOpen(String((opp || [])[0] || sid || '')) }); return true; };\n    const unreg = () => { try { registeredMiniGames = registeredMiniGames.filter(g => g.id !== 'gyxHunt'); } catch (e) {} };\n    addEventListener('gyx:feat', e => { if (e.detail && e.detail.id === 'gyxHunt') e.detail.on ? reg() : unreg(); });\n    if (X.on('gyxHunt') && !reg()) { let n = 0; const iv = setInterval(() => { if (reg() || ++n > 60) clearInterval(iv); }, 500); }\n})();\n\n//# sourceURL=gyx-plugin/TA布置的寻宝.js")(X, typeof applyMacros !== 'undefined' ? applyMacros : undefined); } catch (e) { console.error('[插件] 🗺️ TA布置的寻宝 出错：', e); }
/* ==== 🎡 帮我选 ==== */
try { new Function('X', 'applyMacros', "/* 🎡 帮我选：纠结吃什么、买哪个、去不去的时候，把选项丢给 TA——TA 认真帮你选并说理由（按 TA 记得的你的喜好），或者一起转转盘听天由命。选完过一阵 TA 会来问你「后来怎么样」 */\nif (window.__gyxPick) return; window.__gyxPick = 1;\nX.feat('gyxPick', { n: '🎡 帮我选', desc: '纠结的时候让 TA 帮你选，或者一起转转盘' });\nconst S = X.store('pick');\nlet D = { log: [] };   // [{id, cid, q, opts, pick, why, how:'ta'|'wheel', at, after, ask}]\nconst PRESET = [['今天吃什么', '火锅/麻辣烫/面/饺子/炸鸡/沙拉/寿司/汉堡'], ['喝什么', '奶茶/咖啡/果茶/可乐/白开水'], ['周末干嘛', '睡懒觉/出去逛/看电影/打游戏/收拾房间'], ['要不要', '要/不要'], ['先做哪件', '']];\nconst COL = ['#ff9aa2', '#ffb7b2', '#ffdac1', '#e2f0cb', '#b5ead7', '#c7ceea', '#d5aaff', '#ffc6ff', '#bde0fe', '#fdffb6'];\nasync function taPick(c, q, opts) {\n    const notes = window.gyxNotesData ? ((window.gyxNotesData().notes || {})[String(c.id)] || []).filter(x => x.who === 'me' && x.tier !== 'old').map(x => x.text).slice(0, 12).join('；') : '';\n    if (!X.bailu()) { const j = X.json(await X.ask(`${X.who(c)}\\n她在纠结：「${q}」，选项：${opts.join(' / ')}。\\n${notes ? '你记得她：' + notes + '\\n' : ''}最近的聊天：\\n${X.recent(c, 10)}\\n帮她选一个，理由要具体、像你会说的话（可以结合她最近的状态），30~70 字。\\n只输出 JSON：{\"pick\":\"选项原文\",\"why\":\"\"}`)); if (j && opts.includes(j.pick)) return { pick: j.pick, why: X.plain(j.why || '') }; }\n    const p = X.pick(opts); return { pick: p, why: X.pick([`选「${p}」。别纠结了，听我的。`, `我觉得「${p}」，你上次说过想试试的吧？`, `「${p}」！就这么定了，不好再怪我。`, `闭着眼都选「${p}」，相信我。`]) };\n}\nlet SP = null;\nfunction wheel(opts, rot) { const n = opts.length, R = 120, a = 2 * Math.PI / n; return `<svg viewBox=\"-130 -130 260 260\" width=\"240\" height=\"240\" style=\"transform:rotate(${rot}deg);transition:transform 3.6s cubic-bezier(.17,.89,.22,1)\">${opts.map((o, i) => { const a0 = i * a - Math.PI / 2, a1 = a0 + a, x0 = R * Math.cos(a0), y0 = R * Math.sin(a0), x1 = R * Math.cos(a1), y1 = R * Math.sin(a1), m = (a0 + a1) / 2; return `<path d=\"M0 0 L${x0.toFixed(1)} ${y0.toFixed(1)} A${R} ${R} 0 ${a > Math.PI ? 1 : 0} 1 ${x1.toFixed(1)} ${y1.toFixed(1)}Z\" fill=\"${COL[i % COL.length]}\" stroke=\"#fff\" stroke-width=\"2\"/><text x=\"${(R * .62 * Math.cos(m)).toFixed(1)}\" y=\"${(R * .62 * Math.sin(m)).toFixed(1)}\" font-size=\"${n > 7 ? 11 : 13}\" text-anchor=\"middle\" dominant-baseline=\"middle\" fill=\"#444\">${X.esc(o.slice(0, 6))}</text>`; }).join('')}<circle r=\"16\" fill=\"#fff\" stroke=\"#eee\"/></svg>`; }\nconst optsOf = () => ((document.getElementById('gyxPkO') || {}).value || '').split(/[\\/／,，、\\n]/).map(s => s.trim()).filter(Boolean);\nwindow.gyxPickPreset = i => { const [q, o] = PRESET[i]; document.getElementById('gyxPkQ').value = q; document.getElementById('gyxPkO').value = o; };\nwindow.gyxPickTa = async cid => { const c = X.char(cid), q = ((document.getElementById('gyxPkQ') || {}).value || '').trim() || '帮我选', opts = optsOf(); if (!c || opts.length < 2) { X.toast('🎡 至少给两个选项', '用 / 隔开'); return null; } const r = await taPick(c, q, opts); const it = { id: 'pk' + Date.now().toString(36), cid: String(cid), q, opts, pick: r.pick, why: r.why, how: 'ta', at: Date.now() }; D.log.unshift(it); await S.set('d', D); window.gyxPickOpen(cid, it.id); return it; };\nwindow.gyxPickSpin = async cid => {\n    const c = X.char(cid), q = ((document.getElementById('gyxPkQ') || {}).value || '').trim() || '转盘', opts = optsOf(); if (!c || opts.length < 2) { X.toast('🎡 至少给两个选项', '用 / 隔开'); return null; }\n    const i = Math.floor(Math.random() * opts.length), n = opts.length, rot = 360 * 6 - (i + .5) * 360 / n; const box = document.getElementById('gyxPkWheel'); box.innerHTML = `<div class=\"pk-ptr\">▼</div>` + wheel(opts, 0); await new Promise(r => setTimeout(r, 30)); box.querySelector('svg').style.transform = `rotate(${rot}deg)`;\n    await new Promise(r => setTimeout(r, SP === 'fast' ? 50 : 3700));\n    const why = X.bailu() ? X.pick([`转到「${opts[i]}」了！老天都这么说了。`, `「${opts[i]}」～是不是心里偷偷希望是这个？`, `转盘说「${opts[i]}」，那就它了。`]) : X.plain(await X.ask(`${X.who(c)}\\n她纠结「${q}」（${opts.join(' / ')}），你们一起转了转盘，转到「${opts[i]}」。说一句反应（如果你觉得她其实想要别的，也可以说）。`) || `转到「${opts[i]}」！`);\n    const it = { id: 'pk' + Date.now().toString(36), cid: String(cid), q, opts, pick: opts[i], why, how: 'wheel', at: Date.now() }; D.log.unshift(it); await S.set('d', D); window.gyxPickOpen(cid, it.id); return it;\n};\nwindow.gyxPickAfter = async (id, v) => { const x = D.log.find(y => y.id === id); if (x) { x.after = v; await S.set('d', D); } };\nwindow.gyxPickDel = async id => { const x = D.log.find(y => y.id === id); D.log = D.log.filter(y => y.id !== id); await S.set('d', D); window.gyxPickOpen(x && x.cid); };\nwindow.gyxPickData = () => D;\nwindow.gyxPickOpen = function (who, hl) {\n    const c = X.char(who) || X.cur(); if (!c) return; const cid = String(c.id), last = hl && D.log.find(x => x.id === hl);\n    X.panel('gyxPkOv', '🎡 帮我选', `<div class=\"gyx-row\">${X.whoSel(cid, 'gyxPickOpen')}</div>\n        <div class=\"gyx-row\">${PRESET.map((p, i) => `<span class=\"gyx-chip\" onclick=\"gyxPickPreset(${i})\">${p[0]}</span>`).join('')}</div>\n        <input id=\"gyxPkQ\" class=\"gyx-in\" placeholder=\"纠结什么？\" value=\"${last ? X.esc(last.q) : ''}\"><textarea id=\"gyxPkO\" class=\"gyx-in\" rows=\"2\" style=\"margin-top:6px\" placeholder=\"选项，用 / 隔开：火锅 / 麻辣烫 / 面\">${last ? X.esc(last.opts.join(' / ')) : ''}</textarea>\n        <div class=\"gyx-row\"><button class=\"gyx-btn\" onclick=\"this.disabled=true;this.textContent='TA 在想…';gyxPickTa('${cid}')\">让 TA 帮我选</button><button class=\"gyx-btn lite\" onclick=\"this.disabled=true;gyxPickSpin('${cid}')\">一起转转盘</button></div>\n        <div id=\"gyxPkWheel\" class=\"pk-wh\"></div>\n        ${last ? `<div class=\"gyx-card pk-res\"><em>${X.esc(X.name(c))} 说</em><b>${X.esc(last.pick)}</b><div>${X.esc(last.why)}</div></div>` : ''}\n        <div style=\"font-weight:700;margin:12px 0 4px\">选过的</div>${D.log.filter(x => x.cid === cid).slice(0, 20).map(x => `<div class=\"pk-it\"><span>${X.esc(x.q)}：<b>${X.esc(x.pick)}</b> <em>${x.how === 'wheel' ? '🎡' : '💬'} ${new Date(x.at).toLocaleDateString()}</em></span><input class=\"gyx-who\" placeholder=\"后来怎么样？\" value=\"${X.esc(x.after || '')}\" onchange=\"gyxPickAfter('${x.id}',this.value)\"><i onclick=\"gyxPickDel('${x.id}')\">删</i></div>`).join('') || '<div class=\"gyx-tip\">还没选过</div>'}`);\n};\nwindow.__gyxPickFast = () => { SP = 'fast'; };\nX.ctx(id => { const x = D.log.find(y => y.cid === String(id) && Date.now() - y.at < 864e5); return x ? `【今天你帮她选过】「${x.q}」→ ${x.pick}${x.after ? '（后来：' + x.after + '）' : ''}。` : ''; }, 'gyxPick');\nX.action({ key: 'gyx_pick', label: '问她上次帮她选的那件事后来怎么样', hint: '帮我选', need: c => D.log.some(x => x.cid === String(c.id) && !x.ask && !x.after && Date.now() - x.at > 3 * 36e5 && Date.now() - x.at < 3 * 864e5),\n    run: async c => { const x = D.log.find(y => y.cid === String(c.id) && !y.ask && !y.after && Date.now() - y.at > 3 * 36e5); x.ask = Date.now(); await S.set('d', D); return (await X.reach(c, `之前她纠结「${x.q}」，你帮她选了「${x.pick}」。问问她后来怎么样，选对了没`)) ? '问你后来怎么样' : null; } }, 'gyxPick');\nX.today(() => ({ title: '🎡 帮我选', rows: D.log.filter(x => X.day(new Date(x.at)) === X.day()).map(x => ({ t: x.how === 'wheel' ? '转盘' : 'TA 选', x: X.esc(x.q) + '：' + X.esc(x.pick), go: `gyxPickOpen('${x.cid}')` })) }), 'gyxPick');\nX.widget('gyxPickW', { n: '帮我选', sizes: ['s', 'm'], tap: () => window.gyxPickOpen(), r: w => { const x = D.log[0]; return X.gw(w, '🎡', '帮我选', x ? [X.esc(x.pick), X.esc(x.q)] : ['纠结了？']); } }, 'gyxPick');\nX.memArr({ k: 'gyxPick', ico: '🎡', n: '帮我选', d: '纠结过的事、选了什么、后来怎么样', arr: () => D.log, text: x => x.q + '→' + x.pick + (x.after ? '｜后来：' + x.after : ''), edit: (x, v) => { const m = v.match(/^(.*?)→(.*?)(?:｜后来：(.*))?$/); if (m) { x.q = m[1]; x.pick = m[2]; if (m[3] != null) x.after = m[3]; } }, meta: x => (x.how === 'wheel' ? '转盘' : 'TA 选的') + ' · ' + new Date(x.at).toLocaleDateString(), save: () => S.set('d', D) }, 'gyxPick');\nX.css('gyxPkCss', `.pk-wh{position:relative;display:flex;justify-content:center;margin:6px 0}.pk-ptr{position:absolute;top:-4px;left:50%;transform:translateX(-50%);z-index:2;color:#e0567a;font-size:20px}.pk-res em{font-style:normal;font-size:12px;color:#999}.pk-res b{display:block;font-size:22px;margin:4px 0}.pk-it{display:flex;gap:6px;align-items:center;padding:6px 2px;border-bottom:1px solid #f3f3f3;font-size:13.5px;flex-wrap:wrap}.pk-it span{flex:1;min-width:150px}.pk-it em{font-style:normal;font-size:11px;color:#aaa}.pk-it input{width:130px}.pk-it i{font-style:normal;font-size:11px;color:#aaa;cursor:pointer}`);\nX.mini({ id: 'gyxPick', icon: '🎡', title: '帮我选', desc: '纠结的时候让 TA 帮你选 / 转转盘', cat: '生活', onOpen: () => window.gyxPickOpen() });\n(async () => { D = Object.assign(D, await S.get('d', {})); D.log = D.log || []; })();\n\n// 🎮 放进聊天里的游戏列表（和五子棋、UNO、猜拳在一起）；小功能里就不单独占一格了（js/79 看到这里登记了会藏起来）\n(function () {\n    const reg = () => { if (typeof registerMiniGame !== 'function') return false; registerMiniGame({ id: 'gyxPick', name: '帮我选', icon: '🎡', getStatus: () => null, onResume: () => window.gyxPickOpen(), onStart: (sid, opp) => window.gyxPickOpen(String((opp || [])[0] || sid || '')) }); return true; };\n    const unreg = () => { try { registeredMiniGames = registeredMiniGames.filter(g => g.id !== 'gyxPick'); } catch (e) {} };\n    addEventListener('gyx:feat', e => { if (e.detail && e.detail.id === 'gyxPick') e.detail.on ? reg() : unreg(); });\n    if (X.on('gyxPick') && !reg()) { let n = 0; const iv = setInterval(() => { if (reg() || ++n > 60) clearInterval(iv); }, 500); }\n})();\n\n//# sourceURL=gyx-plugin/帮我选.js")(X, typeof applyMacros !== 'undefined' ? applyMacros : undefined); } catch (e) { console.error('[插件] 🎡 帮我选 出错：', e); }
/* ==== 🎲 跑团 ==== */
try { new Function('X', 'applyMacros', "/* 🎲 跑团：带骰子的 TRPG。开一团时选题材（奇幻 / 克苏鲁 / 都市怪谈 / 校园 / 武侠 / 自己写），TA 当主持人（KP）或者跟你组队当队友；你有一张小角色卡（四项属性 + 血量），每次行动掷骰判定，大成功 / 大失败都有。也能在聊天的 🎮 里开 */\nif (window.__gyxTrpg) return; window.__gyxTrpg = 1;\nX.feat('gyxTrpg', { n: '🎲 跑团', desc: '带骰子的 TRPG，TA 当主持人或者你的队友' });\nconst S = X.store('trpg');\nlet D = { runs: [] };   // runs: {id,cid,at,genre,role:'gm'|'mate',title,me:{name,st:{力量,敏捷,智力,魅力},hp,max},log:[{who,t,roll}],end,sum}\nconst GEN = { fantasy: '奇幻冒险', coc: '克苏鲁 / 调查', urban: '都市怪谈', campus: '校园悬疑', wuxia: '武侠江湖', scifi: '星际科幻' };\nconst STATS = ['力量', '敏捷', '智力', '魅力'];\nconst run = id => D.runs.find(x => x.id === id);\nconst saveD = () => S.set('d', D);\nconst d = n => 1 + Math.floor(Math.random() * n);\nfunction roll(expr) { const m = String(expr || 'd20').match(/^(\\d*)d(\\d+)([+-]\\d+)?$/i); if (!m) return null; const k = +(m[1] || 1), n = +m[2], add = +(m[3] || 0); const rs = Array.from({ length: Math.min(k, 10) }, () => d(n)); return { expr, rs, add, total: rs.reduce((a, b) => a + b, 0) + add, n }; }\nconst mod = v => Math.floor((v - 10) / 2);\nfunction grade(r) { if (r.n === 20 && r.rs.length === 1) { if (r.rs[0] === 20) return '大成功'; if (r.rs[0] === 1) return '大失败'; } return ''; }\nasync function gm(R, ask) {\n    const c = X.char(R.cid), me = X.me(c);\n    const hist = R.log.slice(-16).map(x => (x.who === 'gm' ? '主持人' : x.who === 'ta' ? X.name(c) : me) + '：' + x.t + (x.roll ? `（掷骰 ${x.roll}）` : '')).join('\\n');\n    if (X.bailu()) return { t: X.pick(['你推开那扇门，里面很暗。', '远处传来脚步声。', '骰子落定，命运往前走了一步。']), need: 'd20' };\n    const sheet = `${me}的角色「${R.me.name}」：${STATS.map(s => s + R.me.st[s]).join(' ')}，HP ${R.me.hp}/${R.me.max}`;\n    const who = R.role === 'gm' ? `你是这场跑团的主持人（KP/DM），用你自己的说话方式带团（你是${X.name(c)}，可以偶尔夹带私心偏向她，但规则要公正）。` : `这场跑团由一个旁白主持人带，你（${X.name(c)}）是她的队友，你也有自己的角色，会跟她商量、护着她、也会自己行动。旁白和你的话都由你来写，旁白写在 gm，你自己的台词写在 ta。`;\n    const r = X.json(await X.ask(`${X.who(c)}\\n${who}\\n题材：${GEN[R.genre] || R.genre}。团名《${R.title}》。\\n${sheet}\\n规则：她行动时如果有风险，要求她掷骰（d20 + 对应属性修正，难度 DC 10~18）；你只叙述结果，不替她决定行动；HP 降到 0 就是倒下。\\n最近：\\n${hist || '（刚开团）'}\\n${ask}\\n输出 JSON：{\"gm\":\"主持人叙述（80~180 字，第二人称对她说）\",\"ta\":\"${R.role === 'mate' ? '你作为队友说的一句话（可空）' : ''}\",\"need\":\"下一步要她掷的骰子，如 d20 / 2d6；不需要就空\",\"stat\":\"这次判定用哪项属性（力量/敏捷/智力/魅力，可空）\",\"dc\":难度数字或 null,\"hp\":这一步她 HP 的变化（负数是受伤，0 是没变）,\"end\":true/false 这一团是否结束}`));\n    return r;\n}\nfunction apply(R, r) {\n    if (!r) { R.log.push({ who: 'gm', t: '（主持人卡壳了，再试一次）', at: Date.now() }); return; }\n    if (r.gm) R.log.push({ who: 'gm', t: X.plain(r.gm), at: Date.now() });\n    if (r.ta) R.log.push({ who: 'ta', t: X.plain(r.ta), at: Date.now() });\n    const hp = +r.hp || 0; if (hp) { R.me.hp = Math.max(0, Math.min(R.me.max, R.me.hp + hp)); R.log.push({ who: 'sys', t: `HP ${hp > 0 ? '+' : ''}${hp} → ${R.me.hp}/${R.me.max}`, at: Date.now() }); }\n    R.need = r.need ? String(r.need).trim().toLowerCase() : ''; R.stat = STATS.includes(r.stat) ? r.stat : ''; R.dc = +r.dc || null;\n    if (r.end || R.me.hp <= 0) R.end = R.end || Date.now();\n}\nlet BUSY = false;\nasync function act(R, text, rollRes) {\n    if (BUSY) return; BUSY = true; paint();\n    try {\n        if (text) R.log.push({ who: 'me', t: text, at: Date.now(), roll: rollRes ? `${rollRes.expr}=${rollRes.total}${rollRes.g ? ' ' + rollRes.g : ''}` : '' });\n        const ask = rollRes ? `她的行动：「${text || '（直接掷骰）'}」，掷了 ${rollRes.expr}：${rollRes.rs.join('+')}${rollRes.add ? (rollRes.add > 0 ? '+' : '') + rollRes.add : ''} = ${rollRes.total}${rollRes.g ? '（' + rollRes.g + '）' : ''}${R.dc ? `，难度 ${R.dc}` : ''}。按结果叙述。` : `她的行动：「${text}」。需要判定就叫她掷骰，不需要就直接叙述。`;\n        apply(R, await gm(R, ask));\n        if (R.end && !R.sum) R.sum = X.plain(X.bailu() ? '' : (await X.ask(`${X.who(X.char(R.cid))}\\n你们刚跑完一团《${R.title}》。经过：\\n${R.log.slice(-20).map(x => x.t).join('\\n')}\\n用一句话（30 字以内）写这团最难忘的一刻。只输出这一句。`)) || '') || `跑完了《${R.title}》`;\n        await saveD();\n    } finally { BUSY = false; paint(); }\n}\nwindow.gyxTrpgDo = async id => { const R = run(id), inp = document.getElementById('gyxTpIn'); if (!R) return; const t = (inp && inp.value || '').trim(); if (!t) return; inp.value = ''; await act(R, t); };\nwindow.gyxTrpgRoll = async id => {\n    const R = run(id); if (!R) return; const inp = document.getElementById('gyxTpIn'); const t = (inp && inp.value || '').trim(); if (inp) inp.value = '';\n    const r = roll(R.need || 'd20'); if (!r) return; if (R.stat && /d20/.test(r.expr)) { r.add += mod(R.me.st[R.stat]); r.total += mod(R.me.st[R.stat]); } r.g = grade(r);\n    const dz = document.getElementById('gyxTpDice'); if (dz) { dz.classList.remove('go'); void dz.offsetWidth; dz.textContent = r.total; dz.classList.add('go'); }\n    await new Promise(z => setTimeout(z, 700)); await act(R, t || `${R.stat ? R.stat + '判定' : '掷骰'}`, r);\n};\nwindow.gyxTrpgFree = (expr) => { const r = roll(expr); if (r) X.toast(X.v('🎲 骰子落定', '🎲 掷出来了', '🎲 咕噜咕噜'), `${expr}：${r.rs.join(' + ')}${r.add ? ' ' + (r.add > 0 ? '+' : '') + r.add : ''} = ${r.total}`); return r; };\nasync function newRun(c, genre, role, why) {\n    const st = {}; STATS.forEach(s => { st[s] = [d(6), d(6), d(6), d(6)].sort((a, b) => b - a).slice(0, 3).reduce((a, b) => a + b, 0); });\n    const R = { id: 'tp' + Date.now().toString(36), cid: String(c.id), at: Date.now(), genre, role, title: '', me: { name: X.me(c), st, hp: 10 + mod(st['力量']) * 2 + 4, max: 0 }, log: [] };\n    R.me.max = R.me.hp;\n    const t = X.bailu() ? null : X.json(await X.ask(`${X.who(c)}\\n你要和她跑一团「${GEN[genre] || genre}」${why ? '，起因：' + why : ''}。起一个团名，再写一句开场钩子。输出 JSON：{\"title\":\"团名（12 字以内）\",\"hook\":\"一句钩子\"}`));\n    R.title = X.plain((t && t.title) || X.pick(['雾港来信', '第七层地下室', '无人车站', '月下山门'])).slice(0, 16);\n    D.runs.unshift(R); D.runs = D.runs.slice(0, 30);\n    apply(R, await gm(R, `开团。${t && t.hook ? '钩子：' + t.hook + '。' : ''}介绍场景，给她第一个选择。`)); await saveD(); return R;\n}\nwindow.gyxTrpgNew = async (cid) => {\n    const g = (document.querySelector('#gyxTpOv .tp-g.on') || {}).dataset || {}, r = (document.querySelector('#gyxTpOv .tp-r.on') || {}).dataset || {};\n    const own = ((document.getElementById('gyxTpOwn') || {}).value || '').trim();\n    const R = await newRun(X.char(cid) || X.cur(), own || g.k || 'fantasy', r.k || 'gm'); window.gyxTrpgOpen(R.id);\n};\nwindow.gyxTrpgPick = (el, cls) => { document.querySelectorAll('#gyxTpOv .' + cls).forEach(x => x.classList.remove('on')); el.classList.add('on'); };\nlet CUR = null;\nfunction paint() {\n    const R = CUR && run(CUR), box = document.getElementById('gyxTpLog'); if (!R || !box) return;\n    const c = X.char(R.cid);\n    box.innerHTML = R.log.map(x => `<div class=\"tp-l ${x.who}\">${x.who === 'gm' ? '' : `<b>${x.who === 'ta' ? X.esc(X.name(c)) : x.who === 'me' ? X.esc(R.me.name) : '⚙️'}</b>`}${X.esc(x.t)}${x.roll ? ` <em>🎲 ${X.esc(x.roll)}</em>` : ''}</div>`).join('') + (BUSY ? '<div class=\"tp-l gm\">…</div>' : '');\n    box.scrollTop = box.scrollHeight;\n    const nd = document.getElementById('gyxTpNeed'); if (nd) nd.innerHTML = R.end ? '这一团结束了' : R.need ? `要你掷 <b>${X.esc(R.need)}</b>${R.stat ? `（${R.stat} ${mod(R.me.st[R.stat]) >= 0 ? '+' : ''}${mod(R.me.st[R.stat])}）` : ''}${R.dc ? ` · 难度 ${R.dc}` : ''}` : '说说你要做什么';\n    const hp = document.getElementById('gyxTpHp'); if (hp) hp.textContent = `❤️ ${R.me.hp}/${R.me.max}`;\n}\nwindow.gyxTrpgOpen = function (id, who) {\n    const R = id ? run(id) : null; const c = R ? X.char(R.cid) : (X.char(who) || X.cur()); if (!c) return;\n    if (!R) {\n        CUR = null; const L = D.runs.filter(x => x.cid === String(c.id));\n        X.panel('gyxTpOv', '🎲 跑团', `<div class=\"gyx-row\">${X.whoSel(c.id, 'gyxTrpgWho')}</div>\n            <div class=\"gyx-tip\">题材</div><div class=\"gyx-row\">${Object.entries(GEN).map(([k, n], i) => `<span class=\"gyx-chip tp-g${i ? '' : ' on'}\" data-k=\"${k}\" onclick=\"gyxTrpgPick(this,'tp-g')\">${n}</span>`).join('')}</div>\n            <input id=\"gyxTpOwn\" class=\"gyx-in\" placeholder=\"或者自己写个题材 / 世界观（可空）\">\n            <div class=\"gyx-tip\">TA 的身份</div><div class=\"gyx-row\"><span class=\"gyx-chip tp-r on\" data-k=\"gm\" onclick=\"gyxTrpgPick(this,'tp-r')\">TA 当主持人</span><span class=\"gyx-chip tp-r\" data-k=\"mate\" onclick=\"gyxTrpgPick(this,'tp-r')\">TA 是我的队友</span></div>\n            <div class=\"gyx-row\"><button class=\"gyx-btn\" onclick=\"this.disabled=true;this.textContent='TA 在准备…';gyxTrpgNew('${c.id}')\">开一团</button><span class=\"gyx-chip\" onclick=\"gyxTrpgFree('d20')\">🎲 随手掷个 d20</span></div>\n            ${L.length ? '<div class=\"gyx-tip\">跑过的团</div>' + L.map(x => `<div class=\"gyx-card\" style=\"cursor:pointer\" onclick=\"gyxTrpgOpen('${x.id}')\"><b>${X.esc(x.title)}</b> <span class=\"gyx-tip\">${GEN[x.genre] || X.esc(x.genre)} · ${x.role === 'gm' ? 'TA 主持' : 'TA 是队友'} · ${x.end ? '已结束' : '进行中'}</span>${x.sum ? `<div>${X.esc(x.sum)}</div>` : ''}</div>`).join('') : ''}`);\n        return;\n    }\n    CUR = R.id;\n    X.panel('gyxTpOv', '🎲 ' + X.esc(R.title), `<div class=\"tp-sheet\"><b>${X.esc(R.me.name)}</b>${STATS.map(s => `<span>${s} ${R.me.st[s]}</span>`).join('')}<span id=\"gyxTpHp\"></span></div>\n        <div class=\"tp-log\" id=\"gyxTpLog\"></div><div class=\"tp-need\"><span id=\"gyxTpDice\" class=\"tp-dice\">🎲</span><span id=\"gyxTpNeed\"></span></div>\n        ${R.end ? `<div class=\"gyx-card\">${X.esc(R.sum || '')}</div>` : `<textarea id=\"gyxTpIn\" class=\"gyx-in\" rows=\"2\" placeholder=\"你要做什么？（比如：我小心地推开门，往里看）\"></textarea>\n        <div class=\"gyx-row\"><button class=\"gyx-btn\" onclick=\"gyxTrpgDo('${R.id}')\">行动</button><button class=\"gyx-btn\" onclick=\"gyxTrpgRoll('${R.id}')\">🎲 掷骰</button>${['d4', 'd6', '2d6', 'd100'].map(e => `<span class=\"gyx-chip\" onclick=\"gyxTrpgFree('${e}')\">${e}</span>`).join('')}</div>`}\n        <div class=\"gyx-row\"><button class=\"gyx-btn lite\" onclick=\"gyxTrpgOpen(null,'${R.cid}')\">所有团</button></div>`, 'gyx-trpg');\n    paint();\n};\nwindow.gyxTrpgWho = cid => window.gyxTrpgOpen(null, cid);\nwindow.gyxTrpgData = () => D;\nX.ctx(id => { const R = D.runs.find(x => x.cid === String(id)); if (!R) return ''; return !R.end ? `【你们正在跑团】《${R.title}》（${GEN[R.genre] || R.genre}，${R.role === 'gm' ? '你是主持人' : '你是她的队友'}），她的角色 HP ${R.me.hp}/${R.me.max}。` : Date.now() - R.end < 2 * 864e5 && R.sum ? `【你们刚跑完一团《${R.title}》】${R.sum}` : ''; }, 'gyxTrpg');\nX.action({ key: 'gyx_trpg', label: '想和她跑一团（你来当主持人，或者当她的队友）', hint: '挑个她可能喜欢的题材', need: c => !D.runs.some(x => x.cid === String(c.id) && (!x.end || Date.now() - x.at < 3 * 864e5)),\n    run: async c => { const R = await newRun(c, X.pick(Object.keys(GEN)), X.pick(['gm', 'mate'])); X.notify(c, `🎲 ${X.esc(X.name(c))} ${X.v('开了一团，等你上车', '摆好了骰子，叫你来跑团', '准备了一场跑团')}：${X.esc(R.title)}`, GEN[R.genre] || '', () => window.gyxTrpgOpen(R.id)); return (await X.reach(c, `你准备好了一场跑团《${R.title}》（${GEN[R.genre]}，${R.role === 'gm' ? '你当主持人' : '你当她的队友'}），叫她来玩`)) ? '开了一团：' + R.title : null; } }, 'gyxTrpg');\nX.today(() => ({ title: '🎲 跑团', rows: D.runs.filter(x => X.day(new Date(x.at)) === X.day() || (x.end && X.day(new Date(x.end)) === X.day())).slice(0, 3).map(x => ({ t: X.esc(X.name(X.char(x.cid))), x: (x.end ? '跑完了 ' : '进行中 ') + X.esc(x.title), go: `gyxTrpgOpen('${x.id}')` })) }), 'gyxTrpg');\nX.widget('gyxTrpgW', { n: '跑团', sizes: ['s', 'm'], tap: () => { const c = X.cur(), R = c && D.runs.find(x => x.cid === String(c.id) && !x.end); window.gyxTrpgOpen(R ? R.id : null); }, r: w => { const c = X.cur(), R = c && D.runs.find(x => x.cid === String(c.id)); return X.gw(w, '🎲', '跑团', R ? [R.end ? '上一团：' + X.esc(R.title) : '进行中 · ❤️ ' + R.me.hp, X.esc(R.sum || GEN[R.genre] || '')] : ['还没开过团', '点我开一团']); } }, 'gyxTrpg');\nX.memArr({ k: 'gyxTrpg', ico: '🎲', n: '跑团', d: '跑过的团和最难忘的一刻', arr: () => D.runs, field: 'sum', text: x => `《${x.title}》${x.sum || '（进行中）'}`, edit: (x, v) => { x.sum = String(v).replace(/^《[^》]*》/, ''); }, save: saveD }, 'gyxTrpg');\nX.css('gyxTpCss', `.gyx-trpg .gyx-box{width:min(560px,100%)}.tp-sheet{display:flex;flex-wrap:wrap;gap:6px;align-items:center;font-size:12.5px;background:#f7f7f9;border-radius:14px;padding:8px 10px}.tp-sheet span{background:#fff;border-radius:8px;padding:2px 7px}\n.tp-log{max-height:46vh;overflow:auto;margin:8px 0;font-size:14px;line-height:1.75}.tp-l{margin:6px 0}.tp-l.gm{background:#f3f0ff;border-radius:12px;padding:8px 11px;font-family:Georgia,\"Songti SC\",serif}.tp-l b{color:#8e8e93;font-weight:500;margin-right:6px}.tp-l.me{text-align:right}.tp-l.sys{font-size:12px;color:#ff3b30}.tp-l em{font-style:normal;font-size:12px;color:#7d5fff}\n.tp-need{display:flex;align-items:center;gap:10px;font-size:13px;color:#555}.tp-dice{width:40px;height:40px;border-radius:10px;background:#1d1d1f;color:#fff;display:flex;align-items:center;justify-content:center;font-weight:700}.tp-dice.go{animation:tpRoll .7s ease-out}@keyframes tpRoll{0%{transform:rotate(0) scale(.6)}60%{transform:rotate(540deg) scale(1.2)}100%{transform:rotate(720deg) scale(1)}}`);\nX.mini({ id: 'gyxTrpg', icon: '🎲', title: '跑团', desc: '带骰子的 TRPG，TA 当主持人或者队友', cat: '一起做', onOpen: () => window.gyxTrpgOpen() });\n(() => { const reg = () => { if (typeof registerMiniGame !== 'function') return false; registerMiniGame({ id: 'gyxTrpg', name: '跑团', icon: '🎲', getStatus: () => null, onResume: () => window.gyxTrpgOpen(), onStart: (sid, opp) => window.gyxTrpgOpen(null, String((opp || [])[0] || sid || '')) }); return true; }; if (!reg()) { let n = 0; const iv = setInterval(() => { if (reg() || ++n > 40) clearInterval(iv); }, 500); } })();\n(async () => { D = Object.assign(D, await S.get('d', {})); D.runs = D.runs || []; })();\n\n//# sourceURL=gyx-plugin/跑团.js")(X, typeof applyMacros !== 'undefined' ? applyMacros : undefined); } catch (e) { console.error('[插件] 🎲 跑团 出错：', e); }
/* ==== 🎣 一起钓鱼 ==== */
try { new Function('X', 'applyMacros', "/* 🎣 一起钓鱼：在湖边甩一竿，浮漂动了就点「收！」，手慢了鱼就跑。不同时间、不同季节能钓到的不一样，还有稀有的、传说的，和 TA 扔下去的漂流瓶。攒一本图鉴；卖鱼的钱进钱包。TA 坐在旁边也在钓，钓到好东西会跟你炫耀。也在聊天的 🎮 里 */\nif (window.__gyxFish) return; window.__gyxFish = 1;\nX.feat('gyxFish', { n: '🎣 一起钓鱼', desc: '湖边甩竿、看浮漂收线，攒图鉴；TA 坐旁边也在钓' });\nconst S = X.store('fish');\n// [id, 名字, emoji, 稀有度 1普通 2少见 3稀有 4传说, 价钱, 什么时候有：'day' | 'night' | 'all' | 月份数组]\nconst FISH = [\n    ['carp', '鲫鱼', '🐟', 1, 3, 'all'], ['crucian', '草鱼', '🐟', 1, 4, 'all'], ['minnow', '小白条', '🐟', 1, 1, 'day'], ['bass', '鲈鱼', '🐠', 2, 9, 'all'],\n    ['catfish', '鲶鱼', '🐡', 2, 8, 'night'], ['eel', '黄鳝', '🐍', 2, 10, 'night'], ['shrimp', '小龙虾', '🦞', 1, 5, [5, 6, 7, 8]], ['crab', '大闸蟹', '🦀', 3, 30, [9, 10, 11]],\n    ['koi', '锦鲤', '🎏', 3, 40, 'all'], ['goldfish', '金鱼', '🐠', 2, 12, 'day'], ['turtle', '小乌龟', '🐢', 3, 25, 'all'], ['moonfish', '月光鱼', '🌙', 4, 88, 'night'],\n    ['sakura', '樱花鳟', '🌸', 4, 66, [3, 4]], ['ice', '冰湖鳕', '🧊', 3, 35, [12, 1, 2]], ['boot', '一只旧靴子', '👢', 1, 0, 'all'], ['bottle', 'TA 扔下去的漂流瓶', '🍾', 4, 0, 'all']\n];\nlet D = { dex: {}, log: [], ta: [], coins: 0, rod: 1 };   // dex[id] = {n, best, at}；log: {id,at,fish,cm,by}；ta: TA 钓到的 {cid,at,fish,line}\nconst saveD = () => S.set('d', D);\nconst fish = id => FISH.find(f => f[0] === id);\nconst RAR = ['', '普通', '少见', '稀有', '传说'];\nfunction pool() { const h = new Date().getHours(), m = new Date().getMonth() + 1, night = h >= 19 || h < 6; return FISH.filter(f => f[5] === 'all' || (f[5] === 'night' ? night : f[5] === 'day' ? !night : f[5].includes(m))); }\nfunction roll(bonus) { const P = pool(), w = { 1: 60, 2: 26, 3: 10 + (bonus || 0), 4: 3 + (bonus || 0) / 2 }; let tot = P.reduce((a, f) => a + w[f[3]], 0), r = Math.random() * tot; for (const f of P) { r -= w[f[3]]; if (r <= 0) return f; } return P[0]; }\nlet G = null;   // {state:'wait'|'bite'|'gone', t, timer}\nfunction setState(st, msg) { const box = document.getElementById('gyxFsLake'); if (!box) return; box.dataset.st = st; const m = document.getElementById('gyxFsMsg'); if (m) m.innerHTML = msg || ''; const b = document.getElementById('gyxFsBtn'); if (b) b.textContent = st === 'idle' || st === 'gone' || st === 'got' ? '甩一竿' : st === 'bite' ? '收！' : '等等……'; }\nwindow.gyxFishCast = async () => {\n    if (!G || G.state === 'idle' || G.state === 'gone' || G.state === 'got') {\n        clearTimeout(G && G.timer); G = { state: 'wait' }; setState('wait', X.v('浮漂在水面上晃……', '安静，鱼在附近', '风很轻'));\n        G.timer = setTimeout(() => { if (!G || G.state !== 'wait') return; G.state = 'bite'; G.t = Date.now(); setState('bite', '<b>动了！快收！</b>'); G.timer = setTimeout(() => { if (G && G.state === 'bite') { G.state = 'gone'; setState('gone', X.v('手慢了，鱼跑了', '只剩一圈涟漪', '鱼饵被吃掉了')); } }, 1300); }, X.rnd(2500, 9000));\n        return;\n    }\n    if (G.state === 'wait') { clearTimeout(G.timer); G.state = 'gone'; setState('gone', X.v('收早了，什么都没有', '太心急啦')); return; }\n    if (G.state === 'bite') {\n        clearTimeout(G.timer); const fast = Date.now() - G.t < 450, f = roll(fast ? 6 : 0); G.state = 'got';\n        await land(f, fast);\n    }\n};\nasync function land(f, fast) {\n    const d = D.dex[f[0]] || (D.dex[f[0]] = { n: 0, at: Date.now() }); d.n++; const first = d.n === 1;\n    D.coins += f[4]; try { if (f[4] && window.gyWallet && window.gyWallet.earn) await window.gyWallet.earn('me', f[4], '卖鱼：' + f[1]); } catch (e) {}\n    let cm = ''; const c = X.cur();\n    if (c && f[3] >= 3) cm = X.plain(X.bailu() ? (X.cards(['聊天', '情话'], c, 1)[0] || '') : (await X.ask(`${X.who(c)}\\n你们俩在湖边一起钓鱼，她刚钓到了${RAR[f[3]]}的「${f[1]}」${f[0] === 'bottle' ? '——那是你之前偷偷扔下去的漂流瓶，里面有你写的一句话，现在说出来' : ''}。你坐在旁边，说一句（20 字以内）。只输出这一句。`)) || '');\n    const it = { id: 'fl' + Date.now().toString(36), at: Date.now(), fish: f[0], cm, by: 'me' }; D.log.unshift(it); D.log = D.log.slice(0, 200); await saveD();\n    setState('got', `<span class=\"fs-catch\">${f[2]}</span><b>${X.esc(f[1])}</b> <em class=\"r${f[3]}\">${RAR[f[3]]}</em>${first ? ' · <em>新图鉴！</em>' : ''}${fast ? ' · 手快！' : ''}${f[4] ? ` · +¥${f[4]}` : ''}${cm ? `<div class=\"fs-cm\">💬 ${X.esc(X.name(c))}：${X.esc(cm)}</div>` : ''}`);\n    paintDex();\n}\nfunction paintDex() { const b = document.getElementById('gyxFsDex'); if (!b) return; const got = FISH.filter(f => D.dex[f[0]]).length; b.innerHTML = `<div class=\"gyx-tip\">图鉴 ${got}/${FISH.length} · 卖鱼一共 ¥${D.coins}</div><div class=\"fs-dex\">${FISH.map(f => { const d = D.dex[f[0]]; return `<span class=\"${d ? 'got r' + f[3] : ''}\" title=\"${d ? f[1] + ' ×' + d.n : '？？？'}\">${d ? f[2] : '？'}<i>${d ? X.esc(f[1]) : RAR[f[3]]}</i></span>`; }).join('')}</div>`; }\nasync function taFish(c) {\n    const f = roll(4); const line = X.bailu() ? '' : X.plain(await X.ask(`${X.who(c)}\\n你一个人去湖边钓鱼，钓到了${RAR[f[3]]}的「${f[1]}」。发消息跟她炫耀一句，顺便约她一起来（20 字以内）。只输出这一句。`) || '');\n    const it = { id: 'ft' + Date.now().toString(36), cid: String(c.id), at: Date.now(), fish: f[0], line }; D.ta.unshift(it); D.ta = D.ta.slice(0, 60); await saveD(); return it;\n}\nwindow.gyxFishOpen = function () {\n    const c = X.cur(), h = new Date().getHours(), night = h >= 19 || h < 6; G = { state: 'idle' };\n    X.panel('gyxFsOv', '🎣 一起钓鱼', `<div class=\"fs-lake${night ? ' night' : ''}\" id=\"gyxFsLake\" data-st=\"idle\" onclick=\"gyxFishCast()\"><i class=\"fs-moon\"></i><i class=\"fs-bob\"></i><i class=\"fs-ring\"></i>${c ? `<span class=\"fs-ta\">${(() => { try { return getAvatarHTML(c, 36); } catch (e) { return ''; } })()}<em>${X.esc(X.name(c))} 也在钓</em></span>` : ''}</div>\n        <div class=\"fs-msg\" id=\"gyxFsMsg\">点湖面或者按钮甩一竿。浮漂往下沉的时候赶紧收。</div>\n        <div class=\"gyx-row\"><button class=\"gyx-btn\" id=\"gyxFsBtn\" onclick=\"gyxFishCast()\">甩一竿</button><span class=\"gyx-tip\">${night ? '🌙 晚上：鲶鱼、黄鳝、月光鱼出没' : '☀️ 白天：金鱼、小白条多'}</span></div>\n        <div id=\"gyxFsDex\"></div>\n        ${D.ta.slice(0, 4).map(x => `<div class=\"gyx-tip\">🎣 ${X.esc(X.name(X.char(x.cid)))} 钓到了 ${(fish(x.fish) || [])[2] || ''} ${X.esc((fish(x.fish) || [])[1] || '')}${x.line ? '：' + X.esc(x.line) : ''}</div>`).join('')}`, 'gyx-fish');\n    paintDex();\n};\nwindow.gyxFishData = () => D;\nwindow.gyxFishLand = id => land(fish(id) || FISH[0], false);\nX.ctx(id => { const t = D.ta.find(x => x.cid === String(id) && Date.now() - x.at < 864e5), m = D.log.find(x => Date.now() - x.at < 864e5 && (fish(x.fish) || [])[3] >= 3); return (t ? `【你今天去钓鱼钓到了「${fish(t.fish)[1]}」】` : '') + (m ? `【她今天和你一起钓鱼，钓到了${RAR[fish(m.fish)[3]]}的「${fish(m.fish)[1]}」】` : ''); }, 'gyxFish');\nX.action({ key: 'gyx_fish', label: '去湖边钓鱼，钓到了跟她炫耀、约她一起', hint: '一起钓鱼', need: c => !D.ta.some(x => x.cid === String(c.id) && Date.now() - x.at < 3 * 864e5),\n    run: async c => { const t = await taFish(c), f = fish(t.fish); X.notify(c, `🎣 ${X.esc(X.name(c))} ${X.v('钓到了', '在湖边钓到了', '刚钓上来')} ${f[2]} ${X.esc(f[1])}`, t.line, () => window.gyxFishOpen()); return (await X.reach(c, `你刚钓到了${RAR[f[3]]}的「${f[1]}」，跟她炫耀一下，约她一起来钓${t.line ? '（你想说：' + t.line + '）' : ''}`)) ? '钓到了' + f[1] : null; } }, 'gyxFish');\nX.today(() => { const L = D.log.filter(x => X.day(new Date(x.at)) === X.day()), T = D.ta.filter(x => X.day(new Date(x.at)) === X.day()); return { title: '🎣 钓鱼', rows: (L.length ? [{ t: '你', x: `钓了 ${L.length} 条，最好的是 ${(() => { const b = L.map(x => fish(x.fish)).sort((a, b) => b[3] - a[3])[0]; return b[2] + ' ' + b[1]; })()}`, go: 'gyxFishOpen()' }] : []).concat(T.map(x => ({ t: X.esc(X.name(X.char(x.cid))), x: '钓到了 ' + fish(x.fish)[2] + ' ' + fish(x.fish)[1], go: 'gyxFishOpen()' }))) }; }, 'gyxFish');\nX.widget('gyxFishW', { n: '钓鱼', sizes: ['s', 'm'], tap: () => window.gyxFishOpen(), r: w => { const l = D.log[0], f = l && fish(l.fish); return X.gw(w, f ? f[2] : '🎣', '钓鱼', [f ? '上一条：' + X.esc(f[1]) : '去甩一竿', `图鉴 ${FISH.filter(x => D.dex[x[0]]).length}/${FISH.length}`]); } }, 'gyxFish');\nX.mem({ k: 'gyxFish', ico: '🎣', n: '钓鱼时 TA 说的话', d: '钓到稀有的鱼时 TA 在旁边说的', items: () => D.log.filter(x => x.cm), text: x => `${(fish(x.fish) || [])[1] || ''}｜${x.cm}`, edit: (x, v) => { x.cm = String(v).split('｜').slice(1).join('｜'); }, del: (c, i) => { const it = D.log.filter(x => x.cm)[i]; const j = D.log.indexOf(it); if (j >= 0) D.log.splice(j, 1); }, meta: x => new Date(x.at).toLocaleString(), save: saveD }, 'gyxFish');\nX.css('gyxFsCss', `.gyx-fish .gyx-box{width:min(520px,100%)}.fs-lake{position:relative;height:230px;border-radius:20px;overflow:hidden;cursor:pointer;background:linear-gradient(#bfe6ff 0 38%,#5fb4d9 38%,#2f7fae);user-select:none}.fs-lake.night{background:linear-gradient(#141a3a 0 38%,#1d3b5c 38%,#0e2236)}\n.fs-moon{position:absolute;top:18px;right:28px;width:34px;height:34px;border-radius:50%;background:#fff3b0;box-shadow:0 0 20px #fff3b0;opacity:0}.fs-lake.night .fs-moon{opacity:1}\n.fs-bob{position:absolute;left:48%;top:56%;width:12px;height:20px;border-radius:6px 6px 4px 4px;background:linear-gradient(#ff4d4d 0 50%,#fff 50%);display:none}.fs-ring{position:absolute;left:calc(48% - 14px);top:calc(56% + 12px);width:40px;height:10px;border-radius:50%;border:2px solid rgba(255,255,255,.6);display:none}\n.fs-lake:not([data-st=\"idle\"]) .fs-bob,.fs-lake:not([data-st=\"idle\"]) .fs-ring{display:block}.fs-lake[data-st=\"wait\"] .fs-bob{animation:fsBob 1.6s ease-in-out infinite}.fs-lake[data-st=\"bite\"] .fs-bob{animation:fsBite .25s ease-in-out infinite}.fs-lake[data-st=\"bite\"] .fs-ring{animation:fsRing .5s ease-out infinite}.fs-lake[data-st=\"got\"] .fs-bob,.fs-lake[data-st=\"got\"] .fs-ring,.fs-lake[data-st=\"gone\"] .fs-bob{display:none}\n@keyframes fsBob{50%{transform:translateY(3px)}}@keyframes fsBite{50%{transform:translateY(9px)}}@keyframes fsRing{to{transform:scale(1.8);opacity:0}}\n.fs-ta{position:absolute;left:14px;bottom:12px;display:flex;align-items:center;gap:6px;color:#fff;font-size:12px;text-shadow:0 1px 3px rgba(0,0,0,.4)}.fs-ta em{font-style:normal}\n.fs-msg{min-height:44px;margin:10px 2px;font-size:14px;line-height:1.7}.fs-catch{font-size:28px;vertical-align:middle;margin-right:6px}.fs-msg em{font-style:normal;font-size:12px;padding:1px 7px;border-radius:999px;background:#f2f2f4}.fs-msg em.r3{background:#e6f0ff;color:#2f6fd0}.fs-msg em.r4{background:#fff1d6;color:#b07a00}.fs-cm{margin-top:4px;color:#8e8e93;font-size:13px}\n.fs-dex{display:grid;grid-template-columns:repeat(auto-fill,minmax(64px,1fr));gap:6px}.fs-dex span{background:#f2f2f4;border-radius:12px;padding:6px 2px;text-align:center;font-size:20px;color:#bbb}.fs-dex span i{display:block;font-style:normal;font-size:10.5px;color:#999}.fs-dex span.got{background:#eef7ff;color:inherit}.fs-dex span.r3{background:#e6f0ff}.fs-dex span.r4{background:#fff4d9}`);\nX.mini({ id: 'gyxFish', icon: '🎣', title: '一起钓鱼', desc: '湖边甩竿、看浮漂收线，攒图鉴；TA 也在钓', cat: '一起做', onOpen: () => window.gyxFishOpen() });\n(() => { const reg = () => { if (typeof registerMiniGame !== 'function') return false; registerMiniGame({ id: 'gyxFish', name: '一起钓鱼', icon: '🎣', getStatus: () => null, onResume: () => window.gyxFishOpen(), onStart: () => window.gyxFishOpen() }); return true; }; if (!reg()) { let n = 0; const iv = setInterval(() => { if (reg() || ++n > 40) clearInterval(iv); }, 500); } })();\n(async () => { D = Object.assign(D, await S.get('d', {})); D.dex = D.dex || {}; D.log = D.log || []; D.ta = D.ta || []; })();\n\n//# sourceURL=gyx-plugin/一起钓鱼.js")(X, typeof applyMacros !== 'undefined' ? applyMacros : undefined); } catch (e) { console.error('[插件] 🎣 一起钓鱼 出错：', e); }
