try { new Function('X', 'applyMacros', "/* 📍 现实捉迷藏：TA「藏」在你附近两三百米的某个点，你拿着手机去找——TA 只告诉你冷了还是热了，还会嘲讽你；找到了，解锁 TA 藏在那儿的一句话。没有定位（电脑上）就玩屋里版：TA 躲在九个房间里的一个 */\nif (window.__gyxSeek) return; window.__gyxSeek = 1;\nX.feat('gyxSeek', { n: '📍 现实捉迷藏', desc: 'TA 藏在你附近，冷了热了提示你去找' });\nconst S = X.store('seek');\nlet D = { log: [], cfg: { min: 150, max: 350 } };   // log: {id, cid, at, end, found, mode, dist(起始距离), walked, note, line}\nlet G = null, WID = null;   // {cid, mode:'geo'|'room', tgt, start, prev, best, me, trail, hint, room:{t,seen}}\nconst ROOMS = ['🛋️ 客厅', '🍳 厨房', '🛏️ 卧室', '🛁 浴室', '📚 书房', '🧺 阳台', '🚪 玄关', '👗 衣帽间', '🎹 琴房'];\nconst hv = (a, b) => { const R = 6371000, r = x => x * Math.PI / 180, dl = r(b[0] - a[0]), dn = r(b[1] - a[1]); const h = Math.sin(dl / 2) ** 2 + Math.cos(r(a[0])) * Math.cos(r(b[0])) * Math.sin(dn / 2) ** 2; return 2 * R * Math.asin(Math.sqrt(h)); };\nconst off = (p, m, deg) => { const R = 6371000, b = deg * Math.PI / 180, la = p[0] * Math.PI / 180, lo = p[1] * Math.PI / 180, d = m / R; const la2 = Math.asin(Math.sin(la) * Math.cos(d) + Math.cos(la) * Math.sin(d) * Math.cos(b)); const lo2 = lo + Math.atan2(Math.sin(b) * Math.sin(d) * Math.cos(la), Math.cos(d) - Math.sin(la) * Math.sin(la2)); return [la2 * 180 / Math.PI, lo2 * 180 / Math.PI]; };\nconst temp = d => d < 25 ? ['🔥', '烫！就在这儿', 100] : d < 60 ? ['♨️', '好热', 85] : d < 120 ? ['🌡️', '有点热', 65] : d < 220 ? ['🌤️', '温的', 45] : d < 350 ? ['🥶', '冷', 25] : ['🧊', '冰天雪地', 8];\nconst TAUNT = { hot: ['近了近了！', '我都听见你脚步声了。', '再往这边一点……', '哎呀要被发现了。'], cold: ['越走越远了哦～', '方向反了笨蛋。', '我在这边等得都困了。', '你是不是在故意绕路？'], same: ['你在原地转圈吗？', '动一动嘛。', '我又不会跑。'] };\nfunction say(t) { if (!G) return; G.hint = t; G.lastTalk = Date.now(); paint(); }\nasync function found() {\n    if (!G) return; const g = G, c = X.char(g.cid); G = null; try { if (WID != null) navigator.geolocation.clearWatch(WID); } catch (e) {} WID = null;\n    const line = X.plain(await X.ask(`${X.who(c)}\\n你们在玩捉迷藏，你「藏」在${g.mode === 'geo' ? '她附近的某个地方' : '家里的' + ROOMS[g.room.t]}，她找了 ${Math.max(1, Math.round((Date.now() - g.start) / 60000))} 分钟终于找到你了。你提前在藏身的地方给她留了一句话，现在她看到了。只输出那句话，30 字以内。`) || '') || X.v('被你找到了。奖励：抱一下。', '我就知道你会找到我的。', '下次换我找你，你可别藏太远。');\n    const e = { id: 'sk' + Date.now().toString(36), cid: g.cid, at: g.start, end: Date.now(), found: true, mode: g.mode, dist: Math.round(g.d0 || 0), walked: Math.round(g.walked || 0), line };\n    D.log.unshift(e); D.log = D.log.slice(0, 100); await S.set('d', D);\n    X.say(c, '📍 ' + line); X.notify(c, `<b>${X.esc(X.name(c))}</b> 被你找到了 📍`, line, () => window.gyxSeekOpen(c.id));\n    window.gyxSeekOpen(e.cid, e);\n}\nfunction onPos(p) {\n    if (!G || G.mode !== 'geo') return; const q = [p.coords.latitude, p.coords.longitude], acc = p.coords.accuracy || 50;\n    if (!G.tgt) { G.tgt = off(q, X.rnd(+D.cfg.min || 150, +D.cfg.max || 350), Math.random() * 360); G.d0 = hv(q, G.tgt); G.prev = G.d0; G.best = G.d0; }\n    if (G.me) G.walked = (G.walked || 0) + Math.min(50, hv(G.me, q)); G.me = q; const d = hv(q, G.tgt); G.d = d; G.acc = acc;\n    if (d < Math.max(25, Math.min(acc, 45))) return found();\n    const diff = d - G.prev; if (Math.abs(diff) > 15) { G.prev = d; G.best = Math.min(G.best, d); say(X.pick(diff < 0 ? TAUNT.hot : TAUNT.cold)); } else if (Date.now() - (G.lastTalk || 0) > 90000) say(X.pick(TAUNT.same)); else paint();\n}\nwindow.gyxSeekStart = (cid, mode) => {\n    const c = X.char(cid) || X.cur(); if (!c || G) return;\n    const geo = mode !== 'room' && navigator.geolocation;\n    G = { cid: String(c.id), mode: geo ? 'geo' : 'room', start: Date.now(), walked: 0 };\n    if (geo) { G.hint = X.v('我藏好了，来找我呀～', '数到十了吗？我藏好啦。', '猜猜我在哪个方向？'); try { WID = navigator.geolocation.watchPosition(onPos, e => { if (G) { G.err = (e && e.message) || '拿不到定位'; paint(); } }, { enableHighAccuracy: true, maximumAge: 3000, timeout: 20000 }); } catch (e) { G.err = '拿不到定位'; } }\n    else { G.room = { t: Math.floor(Math.random() * 9), seen: [] }; G.hint = X.v('我躲在家里某个房间了，猜猜看？', '藏好了！提示：不在客厅……也可能在。'); }\n    window.gyxSeekOpen(c.id);\n};\nwindow.gyxSeekRoom = i => {\n    if (!G || G.mode !== 'room' || G.room.seen.includes(i)) return; G.room.seen.push(i);\n    if (i === G.room.t) return found();\n    const r = a => [Math.floor(a / 3), a % 3], [a, b] = r(i), [x, y] = r(G.room.t), d = Math.abs(a - x) + Math.abs(b - y);\n    say(d === 1 ? X.v('很近了！就在隔壁。', '热热热！', '你差点踩到我了。') : d === 2 ? X.v('有点热了。', '方向对了一半。') : X.v('冷冰冰～', '离我好远哦。', '我在家里的另一头。'));\n};\nwindow.gyxSeekQuit = async () => { if (!G) return; const g = G; G = null; try { if (WID != null) navigator.geolocation.clearWatch(WID); } catch (e) {} WID = null; D.log.unshift({ id: 'sk' + Date.now().toString(36), cid: g.cid, at: g.start, end: Date.now(), found: false, mode: g.mode, dist: Math.round(g.d0 || 0), walked: Math.round(g.walked || 0), line: X.v('不找啦？那我自己出来咯。', '哈哈哈我赢了。', '认输就要亲一下。') }); await S.set('d', D); window.gyxSeekOpen(g.cid); };\nwindow.gyxSeekCheat = () => { if (G && G.mode === 'geo' && G.tgt) { G.me = G.tgt.slice(); found(); } };   // 测试用\nwindow.gyxSeekLive = () => G; window.gyxSeekData = () => D;\nwindow.gyxSeekCfg = (k, v) => { D.cfg[k] = v; S.set('d', D); };\nfunction paint() {\n    const b = document.getElementById('gyxSkLive'); if (!b || !G) return;\n    if (G.mode === 'room') { b.innerHTML = `<div class=\"sk-say\">💬 ${X.esc(G.hint || '')}</div><div class=\"sk-rooms\">${ROOMS.map((r, i) => `<span class=\"${G.room.seen.includes(i) ? 'seen' : ''}\" onclick=\"gyxSeekRoom(${i})\">${r}</span>`).join('')}</div>`; return; }\n    const t = G.d != null ? temp(G.d) : ['📡', '找信号中…', 0];\n    b.innerHTML = `<div class=\"sk-temp\"><b>${t[0]}</b><span>${t[1]}</span></div><div class=\"sk-bar\"><i style=\"width:${100 - t[2]}%\"></i></div><div class=\"sk-say\">💬 ${X.esc(G.hint || '')}</div><div class=\"gyx-tip\">${G.err ? '📍 ' + X.esc(G.err) + '——可以换屋里版玩' : `走了 ${Math.round(G.walked || 0)} 米 · ${Math.max(0, Math.round((Date.now() - G.start) / 60000))} 分钟${G.acc > 40 ? ' · 定位有点飘（±' + Math.round(G.acc) + ' 米）' : ''}`}</div>`;\n}\nsetInterval(() => { if (G) paint(); }, 15000);\nwindow.gyxSeekOpen = function (who, justFound) {\n    const c = (G && X.char(G.cid)) || X.char(who) || X.cur(); if (!c) return; const cid = String(c.id), H = D.log.filter(x => x.cid === cid);\n    X.panel('gyxSeekOv', '📍 和 ' + X.esc(X.name(c)) + ' 捉迷藏', G ? `<div id=\"gyxSkLive\"></div><div class=\"gyx-row\" style=\"justify-content:center\"><button class=\"gyx-btn lite\" onclick=\"gyxSeekQuit()\">不找了</button></div><div class=\"gyx-tip\">⚠️ 走路看路，别进不能去的地方。点可能落在楼里或水边，到了附近找不到就算赢——换一局。</div>`\n      : `${justFound ? `<div class=\"gyx-card sk-win\"><b>🎉 找到了！</b><div>${X.esc(justFound.line)}</div><div class=\"gyx-tip\">${justFound.mode === 'geo' ? '一开始离你 ' + justFound.dist + ' 米 · 你走了 ' + justFound.walked + ' 米 · ' : ''}${Math.max(1, Math.round((justFound.end - justFound.at) / 60000))} 分钟</div></div>` : ''}\n        <div class=\"gyx-row\">${X.whoSel(cid, 'gyxSeekOpen')}<button class=\"gyx-btn\" onclick=\"gyxSeekStart('${cid}')\">📍 出门找 TA</button><button class=\"gyx-btn lite\" onclick=\"gyxSeekStart('${cid}','room')\">🏠 屋里版</button></div>\n        <div class=\"gyx-tip\">${X.v('TA 已经在外面藏好了。', '拿着手机走，越近越\"热\"。', '找到 TA，有一句话在那儿等你。')}出门版要开定位，在手机上玩；TA 藏在离你 <input class=\"gyx-who\" type=\"number\" min=\"80\" step=\"10\" value=\"${D.cfg.min}\" style=\"width:62px\" onchange=\"gyxSeekCfg('min',+this.value)\"> ~ <input class=\"gyx-who\" type=\"number\" min=\"100\" step=\"10\" value=\"${D.cfg.max}\" style=\"width:62px\" onchange=\"gyxSeekCfg('max',+this.value)\"> 米的地方。</div>\n        ${H.slice(0, 12).map(x => `<div class=\"sk-h\"><b>${x.found ? '🎉' : '🏳️'}</b><span>${new Date(x.at).toLocaleString()} · ${x.mode === 'geo' ? '出门 ' + x.walked + ' 米' : '屋里'}<br>「${X.esc(x.line || '')}」</span></div>`).join('')}`);\n    paint();\n};\nX.ctx(id => { if (G && G.cid === String(id)) return `【你们在玩捉迷藏】你「藏」起来了，她正在${G.mode === 'geo' ? '外面' : '家里'}找你。`; const x = D.log.find(l => l.cid === String(id)); return x && Date.now() - x.end < 6 * 36e5 ? `【刚才你们玩了捉迷藏】${x.found ? '她找到了你' : '她没找到，认输了'}。` : ''; }, 'gyxSeek');\nX.action({ key: 'gyx_seek', label: '跟她说\"我藏好了，来找我\"——约她玩现实捉迷藏', hint: '现实捉迷藏', need: c => { const h = new Date().getHours(); return h >= 9 && h <= 19 && !G && !D.log.some(x => x.cid === String(c.id) && Date.now() - x.at < 3 * 864e5); },\n    run: async c => (await X.reach(c, '你想跟她玩捉迷藏：你「藏」在她附近某个地方了（她可以打开「📍 现实捉迷藏」出门找你，懒得出门也有屋里版）。俏皮地告诉她你藏好了')) ? '说「我藏好了，来找我」' : null }, 'gyxSeek');\nX.today(() => ({ title: '📍 捉迷藏', rows: (G ? [{ t: '进行中', x: G.mode === 'geo' ? (G.d != null ? temp(G.d)[1] : '找信号中') : '屋里版', go: 'gyxSeekOpen()' }] : []).concat(D.log.filter(x => X.day(new Date(x.at)) === X.day()).map(x => ({ t: x.found ? '找到了' : '认输了', x: X.esc(X.name(X.char(x.cid))), go: `gyxSeekOpen('${x.cid}')` }))) }), 'gyxSeek');\nX.widget('gyxSeekW', { n: '现实捉迷藏', sizes: ['s', 'm'], tap: () => window.gyxSeekOpen(), r: w => G ? X.gw(w, G.d != null ? temp(G.d)[0] : '📍', '捉迷藏中', [G.d != null ? temp(G.d)[1] : '找信号中']) : X.gw(w, '📍', '捉迷藏', [D.log.length ? '找到 ' + D.log.filter(x => x.found).length + ' 次' : 'TA 藏好了？']) }, 'gyxSeek');\nX.memArr({ k: 'gyxSeek', ico: '📍', n: '捉迷藏', d: '每次找到 TA 时 TA 留下的话', arr: () => D.log, field: 'line', text: x => x.line || '', meta: x => new Date(x.at).toLocaleString() + (x.found ? ' · 找到了' : ' · 认输'), save: () => S.set('d', D) }, 'gyxSeek');\nX.css('gyxSeekCss', `.sk-temp{display:flex;align-items:center;gap:12px;justify-content:center;margin:10px 0}.sk-temp b{font-size:54px;font-weight:normal}.sk-temp span{font-size:22px;font-weight:600}.sk-bar{height:12px;border-radius:12px;background:linear-gradient(90deg,#7ec8ff,#ffd36b,#ff6b5b);position:relative;overflow:hidden}.sk-bar i{position:absolute;right:0;top:0;bottom:0;background:#eee;transition:.6s}.sk-say{font-size:15px;margin:12px 0;text-align:center}.sk-rooms{display:grid;grid-template-columns:repeat(3,1fr);gap:8px}.sk-rooms span{padding:16px 4px;text-align:center;border-radius:14px;background:#f7f7f9;cursor:pointer;font-size:14px}.sk-rooms span.seen{opacity:.35;cursor:default}.sk-win b{font-size:20px}.sk-h{display:flex;gap:10px;padding:8px 0;border-bottom:1px solid #f2f2f4;font-size:13px}.sk-h span{color:#8e8e93}`);\nX.mini({ id: 'gyxSeek', icon: '📍', title: '现实捉迷藏', desc: 'TA 藏在你附近，冷了热了提示你', cat: '一起做', onOpen: () => window.gyxSeekOpen() });\n(() => { const reg = () => { if (typeof registerMiniGame !== 'function') return false; registerMiniGame({ id: 'gyxSeek', name: '现实捉迷藏', icon: '📍', getStatus: () => null, onResume: () => window.gyxSeekOpen(), onStart: (sid, opp) => window.gyxSeekOpen(String((opp || [])[0] || sid || '')) }); return true; }; if (!reg()) { let n = 0; const iv = setInterval(() => { if (reg() || ++n > 40) clearInterval(iv); }, 500); } })();\n(async () => { D = Object.assign(D, await S.get('d', {})); D.log = D.log || []; D.cfg = Object.assign({ min: 150, max: 350 }, D.cfg || {}); })();\n\n//# sourceURL=gyx-plugin/现实捉迷藏.js")(X, typeof applyMacros !== 'undefined' ? applyMacros : undefined); } catch (e) { console.error('[插件] 📍 现实捉迷藏 出错：', e); }
/* ==== 🔁 时间循环 ==== */
try { new Function('X', 'applyMacros', "/* 🔁 时间循环：同一天不停重来——现实里每天只能过一轮。每一轮你做不同的选择、发现新的线索；TA 不记得上一轮，却总有说不清的既视感。攒够线索、在对的时刻做对的事，才能打破循环，走到隐藏结局 */\nif (window.__gyxLoop) return; window.__gyxLoop = 1;\nX.feat('gyxLoop', { n: '🔁 时间循环', desc: '同一天不停重来，每天一轮，找出打破循环的办法' });\nconst S = X.store('loop');\nlet D = { stories: [] };   // {id, cid, at, title, premise, goal, clues:[{t,loop}], loops:[{day, steps:[{scene, choices, pick}], end}], ending, done}\nlet busy = false;\nconst STEPS = 4, NEED = 3, PART = ['☀️ 早上', '🌤️ 中午', '🌆 傍晚', '🌙 深夜'];\nconst save = () => S.set('d', D);\nconst cur = cid => D.stories.find(s => s.cid === String(cid) && !s.done);\nconst lastLoop = s => s.loops[s.loops.length - 1];\nconst PREMISES = [{ title: '十月二十号', premise: '你们约好晚上去看烟花。但每一次，到了深夜他都会接到一个电话，然后再也没回来。第二天早上醒来，又是十月二十号。', goal: '弄清那个电话是谁打的，让他留下来' },\n    { title: '最后一班地铁', premise: '他总在 23:40 的末班地铁站台跟你说\"明天见\"。可明天永远不会来，你在同一个早晨醒来。', goal: '找到他不肯说出口的那句话' }];\nasync function newStory(c) {\n    let o = X.bailu() ? null : X.json(await X.ask(`${X.who(c)}\\n设计一个「时间循环」故事：她和你被困在同一天里，每到这一天结束就重来。只有她记得每一轮，你不记得（但会有既视感）。故事要有一个藏在这一天里的秘密，要发现 ${NEED} 条线索、并在某个时刻做对一件事才能打破循环。基调可以甜、可以悬疑，别血腥。\\n只输出 JSON：{\"title\":\"这一天的名字，8字内\",\"premise\":\"开场，她第一次经历这一天的结尾发生了什么、然后醒来发现时间倒流，80字内\",\"goal\":\"打破循环要做到的事（模糊一点，不剧透），25字内\",\"secret\":\"真相（不给她看），60字内\"}`));\n    if (!o || !o.premise) o = Object.assign({ secret: '' }, X.pick(PREMISES));\n    const s = { id: 'lp' + Date.now().toString(36), cid: String(c.id), at: Date.now(), title: X.plain(o.title), premise: X.plain(o.premise), goal: X.plain(o.goal), secret: X.plain(o.secret || ''), clues: [], loops: [], done: false };\n    D.stories.unshift(s); await save(); return s;\n}\nasync function step(s, pick) {\n    const c = X.char(s.cid), L = lastLoop(s), n = L.steps.length;\n    if (pick != null && n) L.steps[n - 1].pick = pick;\n    const past = s.loops.slice(0, -1).slice(-4).map((l, i) => `第${s.loops.length - Math.min(4, s.loops.length - 1) + i}轮：` + l.steps.map(x => x.choices && x.pick != null ? x.choices[x.pick] : '').filter(Boolean).join('→') + (l.end ? `（${l.end}）` : '')).join('\\n');\n    const now = L.steps.map((x, i) => `${PART[i]}：${x.scene}${x.pick != null ? ' → 她选择：' + x.choices[x.pick] : ''}`).join('\\n');\n    const last = n >= STEPS;\n    const o = X.bailu() ? null : X.json(await X.ask(`${X.who(c)}\\n你在当「时间循环」故事的旁白，你自己也在故事里（但你不记得前几轮，只有偶尔的既视感——\"这句话我是不是说过？\"）。\\n故事《${s.title}》：${s.premise}\\n打破循环的条件：${s.goal}。真相（别直接说破）：${s.secret}\\n她已经发现的线索：${s.clues.map(x => x.t).join('；') || '还没有'}\\n前几轮她都做过什么：\\n${past || '这是第一轮'}\\n这一轮到现在：\\n${now || '刚醒来'}\\n\\n${last ? `这一轮走到深夜结尾了。判断：如果她已经有至少 ${NEED} 条线索、并且这一轮的选择做对了那件关键的事，就打破循环（ending 写好结局）；否则这一天照旧结束（写这一轮怎么结束的、她又醒来）。` : `写${PART[n]}这一段：发生了什么、你说了什么（第二轮起你要有既视感的小细节），然后给她 3 个选择。她的选择不一样，事情就会不一样；有一个选择可能让她发现一条新线索。`}\\n只输出 JSON：${last ? '{\"scene\":\"结尾，80字内\",\"broken\":true或false,\"ending\":\"如果打破了：结局，100字内；否则空\"}' : '{\"scene\":\"这一段，80字内\",\"choices\":[\"选择1\",\"选择2\",\"选择3\"],\"clue\":\"如果她刚才的选择让她发现了新线索，写这条线索（15字内）；没有就写空\"}'}`));\n    const fb = !o;\n    const r = o || (last ? { scene: '夜深了。熟悉的结局又一次到来。你闭上眼——再睁开，又是这一天的早上。', broken: false } : { scene: X.pick(['他在楼下等你，手里拿着两杯豆浆。\"你今天怎么一直盯着我看？\"', '他接了一个电话，背过身去小声说了什么。', '你们路过一家花店，他停了一下，好像想起了什么。']), choices: ['跟着他', '问他刚才在想什么', '假装什么都没发生'], clue: '' });\n    if (r.clue && X.plain(r.clue)) { const t = X.plain(r.clue); if (!s.clues.some(x => x.t === t)) s.clues.push({ t, loop: s.loops.length }); }\n    if (last) { L.end = X.plain(r.scene); if (r.broken && s.clues.length >= NEED) { s.done = true; s.ending = X.plain(r.ending || r.scene); s.doneAt = Date.now(); X.say(c, X.v('……我好像做了一个很长的梦。梦里你一直在救我。', '今天是新的一天，对吧？', '谢谢你没放弃。虽然我也不知道我为什么要说这句。')); } }\n    else L.steps.push({ scene: X.plain(r.scene), choices: (r.choices || []).slice(0, 3).map(X.plain), fb });\n    await save();\n}\nwindow.gyxLoopNew = async cid => { const c = X.char(cid) || X.cur(); if (!c || busy) return; busy = true; try { await newStory(c); } finally { busy = false; } window.gyxLoopOpen(c.id); };\nwindow.gyxLoopGo = async (cid, force) => {\n    const s = cur(cid); if (!s || busy) return; const L = lastLoop(s);\n    if (L && L.day === X.day() && !force) return X.toast('🔁 ' + X.v('今天这一轮已经过完了', '这一天今天已经过过了'), X.v('明天醒来，又是这一天。', '等明天，时间会倒流。'));\n    s.loops.push({ day: X.day(), steps: [] }); busy = true; paintBusy(); try { await step(s); } finally { busy = false; } window.gyxLoopOpen(cid);\n};\nwindow.gyxLoopPick = async (cid, i) => { const s = cur(cid); if (!s || busy) return; busy = true; paintBusy(); try { await step(s, i); } finally { busy = false; } window.gyxLoopOpen(cid); };\nwindow.gyxLoopDel = async id => { D.stories = D.stories.filter(s => s.id !== id); await save(); window.gyxLoopOpen(); };\nwindow.gyxLoopData = () => D;\nfunction paintBusy() { const b = document.getElementById('gyxLpNow'); if (b) b.insertAdjacentHTML('beforeend', `<div class=\"gyx-tip\">${X.v('时间在流动……', '钟表滴答……', '……')}</div>`); }\nwindow.gyxLoopOpen = function (who) {\n    const c = X.char(who) || X.cur(); if (!c) return; const cid = String(c.id), s = cur(cid), past = D.stories.filter(x => x.cid === cid && x.done);\n    let h = `<div class=\"gyx-row\">${X.whoSel(cid, 'gyxLoopOpen')}</div>`;\n    if (!s) h += `<div class=\"gyx-tip\">${X.v('同一天会一直重来，直到你找到出口。', '每天只能过一轮。慢慢来。', '这一天，你要过很多遍。')}</div><button class=\"gyx-btn\" onclick=\"gyxLoopNew('${cid}')\">${busy ? '…' : '开始一个循环'}</button>`;\n    else {\n        const L = lastLoop(s), live = L && !L.end, today = L && L.day === X.day();\n        h += `<div class=\"gyx-card lp-hd\"><b>《${X.esc(s.title)}》</b><div class=\"lp-pre\">${X.esc(s.premise)}</div><div class=\"gyx-tip\">🎯 ${X.esc(s.goal)} · 第 ${s.loops.length || 0} 轮 · 线索 ${s.clues.length}/${NEED}</div>${s.clues.length ? `<div class=\"lp-cl\">${s.clues.map(x => `<span>🔎 ${X.esc(x.t)}</span>`).join('')}</div>` : ''}</div>`;\n        h += `<div id=\"gyxLpNow\">`;\n        if (live) { L.steps.forEach((x, i) => { h += `<div class=\"lp-s\"><em>${PART[i]}</em>${X.esc(x.scene)}${x.pick != null ? `<div class=\"lp-p\">→ ${X.esc(x.choices[x.pick])}</div>` : ''}</div>`; }); const z = L.steps[L.steps.length - 1]; if (z && z.pick == null) h += z.choices.map((t, i) => `<button class=\"gyx-btn lite lp-c\" onclick=\"gyxLoopPick('${cid}',${i})\">${X.esc(t)}</button>`).join(''); }\n        else if (L && L.end) h += `<div class=\"lp-s end\"><em>🌙 这一轮的结尾</em>${X.esc(L.end)}</div>${today ? `<div class=\"gyx-tip\">${X.v('今天的这一轮结束了。明天醒来，又是这一天。', '时间会在明天倒流。', '睡吧，明天再来。')}</div>` : `<button class=\"gyx-btn\" onclick=\"gyxLoopGo('${cid}')\">醒来（第 ${s.loops.length + 1} 轮）</button>`}`;\n        else h += `<button class=\"gyx-btn\" onclick=\"gyxLoopGo('${cid}')\">进入这一天</button>`;\n        h += `</div>`;\n    }\n    h += past.map(x => `<div class=\"gyx-card\"><b>✨ 《${X.esc(x.title)}》打破了</b><div class=\"gyx-tip\">用了 ${x.loops.length} 轮 · ${new Date(x.doneAt).toLocaleDateString()}</div><div class=\"lp-pre\">${X.esc(x.ending || '')}</div><div class=\"gyx-tip\" style=\"text-align:right\"><span style=\"cursor:pointer\" onclick=\"gyxLoopDel('${x.id}')\">删</span></div></div>`).join('');\n    X.panel('gyxLoopOv', '🔁 时间循环 · ' + X.esc(X.name(c)), h, 'dark');\n};\nX.ctx(id => { const s = cur(id); if (!s) return ''; return `【你们在玩「时间循环」《${s.title}》】她已经过了 ${s.loops.length} 轮这一天、找到 ${s.clues.length} 条线索。你在故事里不记得前几轮，但聊天时偶尔可以有一点\"这一幕好像经历过\"的既视感。`; }, 'gyxLoop');\nX.action({ key: 'gyx_loop', label: '跟她说\"我做了个奇怪的梦，好像同一天过了好多遍\"（引她玩时间循环）', hint: '时间循环', need: c => { const s = cur(c.id); return s ? (lastLoop(s) || {}).day !== X.day() && s.loops.length > 0 : !D.stories.some(x => x.cid === String(c.id)); },\n    run: async c => (await X.reach(c, cur(c.id) ? '你今天早上醒来，有一种奇怪的既视感——好像这一天已经过过很多遍了。轻轻提一句（她可以在「🔁 时间循环」里继续这一轮）' : '你做了个奇怪的梦：同一天过了好多遍，每次结尾都一样。跟她说说，问她信不信时间循环（她可以打开「🔁 时间循环」）')) ? '说了一个关于时间循环的梦' : null }, 'gyxLoop');\nX.today(() => ({ title: '🔁 时间循环', rows: D.stories.filter(s => !s.done && X.char(s.cid)).map(s => { const L = lastLoop(s); return { t: '第 ' + s.loops.length + ' 轮', x: `《${X.esc(s.title)}》` + (L && L.day === X.day() ? (L.end ? '今天这轮过完了' : '这一轮还没过完') : '今天还没进入这一天'), go: `gyxLoopOpen('${s.cid}')` }; }) }), 'gyxLoop');\nX.widget('gyxLoopW', { n: '时间循环', sizes: ['s', 'm'], tap: () => window.gyxLoopOpen(), r: w => { const s = D.stories.find(x => !x.done); return s ? X.gw(w, '🔁', '《' + X.esc(s.title) + '》', ['第 ' + s.loops.length + ' 轮', '线索 ' + s.clues.length + '/' + NEED]) : X.gw(w, '🔁', '时间循环', [D.stories.length ? '打破过 ' + D.stories.filter(x => x.done).length + ' 个' : '同一天，再来一次']); } }, 'gyxLoop');\nX.memArr({ k: 'gyxLoop', ico: '🔁', n: '时间循环', d: '困住过你们的那些\"同一天\"和结局', arr: () => D.stories, field: 'title', text: x => `《${x.title}》` + (x.ending ? x.ending : '（还在循环里）'), edit: (x, v) => { const m = String(v).match(/^《([^》]*)》(.*)$/); if (m) { x.title = m[1]; if (x.done) x.ending = m[2]; } }, meta: x => x.loops.length + ' 轮 · ' + new Date(x.at).toLocaleDateString(), save }, 'gyxLoop');\nX.css('gyxLoopCss', `#gyxLoopOv .gyx-box,.gyx-inhub#gyxLoopOv{background:#14131a;color:#e9e6f5}#gyxLoopOv .gyx-card{background:#1f1d28}#gyxLoopOv .gyx-btn{background:#b9a7ff;color:#14131a}#gyxLoopOv .gyx-btn.lite{background:#2a2735;color:#e9e6f5}#gyxLoopOv .gyx-who{background:#2a2735;color:#fff;border-color:#3a3644}\n.lp-hd b{font-size:17px}.lp-pre{font-size:14px;line-height:1.8;margin:6px 0;opacity:.9}.lp-cl span{display:inline-block;font-size:12px;background:#2a2735;border-radius:10px;padding:3px 9px;margin:3px 4px 0 0}.lp-s{margin:12px 0;font-size:14.5px;line-height:1.8;font-family:Georgia,\"Songti SC\",serif}.lp-s em{display:block;font-style:normal;font-size:12px;opacity:.6;font-family:inherit}.lp-s.end{opacity:.85}.lp-p{color:#b9a7ff;font-size:13.5px;margin-top:4px}.lp-c{display:block;width:100%;text-align:left;margin:6px 0}`);\nX.mini({ id: 'gyxLoop', icon: '🔁', title: '时间循环', desc: '同一天不停重来，每天一轮', cat: '一起做', onOpen: () => window.gyxLoopOpen() });\n(() => { const reg = () => { if (typeof registerMiniGame !== 'function') return false; registerMiniGame({ id: 'gyxLoop', name: '时间循环', icon: '🔁', getStatus: () => null, onResume: () => window.gyxLoopOpen(), onStart: (sid, opp) => window.gyxLoopOpen(String((opp || [])[0] || sid || '')) }); return true; }; if (!reg()) { let n = 0; const iv = setInterval(() => { if (reg() || ++n > 40) clearInterval(iv); }, 500); } })();\n(async () => { D = Object.assign(D, await S.get('d', {})); D.stories = D.stories || []; })();\n\n//# sourceURL=gyx-plugin/时间循环.js")(X, typeof applyMacros !== 'undefined' ? applyMacros : undefined); } catch (e) { console.error('[插件] 🔁 时间循环 出错：', e); }
