try { new Function('X', 'applyMacros', "/* 🗝️ 双人密室：你和 TA 被关在两个不同的房间，各自只看得到一半线索，只能靠说话合作——你看到\"顺序\"和两个数，TA 那边有另外两个数，可 TA 会按自己的性格描述（会漏、会说偏、会逞强）。凑齐四位密码一起出去 */\nif (window.__gyxRoom) return; window.__gyxRoom = 1;\nX.feat('gyxRoom', { n: '🗝️ 双人密室', desc: '各看一半线索，靠说话合作逃出去' });\nconst S = X.store('room');\nlet D = { log: [] };   // {id, cid, at, end, theme, ok, tries, msgs, secs}\nlet G = null, busy = false;   // {cid, theme, code:[4], order:[obj idx], mine:[{obj,clue,pos}], his:[...], chat:[{who,t}], tries, start}\nconst THEMES = [{ k: '古董店', ico: '🕰️', mine: '落满灰的古董店里间', his: '古董店的地下仓库' }, { k: '游轮', ico: '🚢', mine: '游轮的船长室', his: '游轮的锅炉房' }, { k: '图书馆', ico: '📚', mine: '闭馆后的图书馆阅览室', his: '图书馆的档案室' }, { k: '医院', ico: '🏥', mine: '废弃医院的护士站', his: '废弃医院的药房' }];\nconst OBJ = [['钟', d => `墙上的钟停在 ${d} 点整`], ['书', d => `书架上只有 ${d} 本红色封皮的书`], ['画', d => `一幅画里画了 ${d} 只飞鸟`], ['灯', d => `天花板上亮着 ${d} 盏灯，其余都是坏的`], ['杯', d => `桌上摆着 ${d} 个茶杯，杯口朝下`], ['窗', d => `墙上有 ${d} 扇被钉死的窗`]];\nconst shuf = a => { a = a.slice(); for (let i = a.length - 1; i > 0; i--) { const j = Math.floor(Math.random() * (i + 1)); [a[i], a[j]] = [a[j], a[i]]; } return a; };\nfunction make(cid) {\n    const T = X.pick(THEMES), objs = shuf(OBJ).slice(0, 4), code = objs.map(() => 1 + Math.floor(Math.random() * 9));\n    const pos = shuf([0, 1, 2, 3]), mineIdx = pos.slice(0, 2), hisIdx = pos.slice(2);\n    return { cid: String(cid), theme: T, code, objs: objs.map(o => o[0]), mine: mineIdx.map(i => ({ i, t: objs[i][1](code[i]) })), his: hisIdx.map(i => ({ i, t: objs[i][1](code[i]) })), chat: [], tries: 0, start: Date.now() };\n}\nconst orderNote = g => `门边的铜牌上刻着：「${g.objs.join(' → ')}」`;\nasync function taReply(msg) {\n    const c = X.char(G.cid), g = G;\n    const p = `${X.who(c)}\\n你们在玩「双人密室」：你和她被分别关在两个房间，只能隔着墙/对讲机说话。你在「${g.theme.his}」，你这边看得到的东西：\\n- ${g.his.map(x => x.t).join('\\n- ')}\\n（你这边没有密码锁，锁在她那边；你也不知道她那边有什么，除非她告诉你。）\\n刚才的对话：\\n${g.chat.slice(-10).map(x => (x.who === 'me' ? '她' : '你') + '：' + x.t).join('\\n')}\\n她说：「${msg}」\\n按你的性格回她：可以描述你看到的（别一口气全说完，她问什么答什么；你可以紧张、逞强、开玩笑、说得不够准确，但**数字不能说错**）。也可以问她那边的情况。像隔着墙说话那样，40 字以内。只输出你说的话。`;\n    let t = X.plain(await X.ask(p) || '');\n    if (!t) { const x = X.pick(g.his); t = /多少|几|什么|看到|有/.test(msg) ? X.v(`我这边……${x.t}。`, `等等我看看——${x.t}，就这些了。`) : X.v('你那边怎么样？我这边黑漆漆的。', '别怕，我在呢。你看到什么了？'); }\n    return t;\n}\nwindow.gyxRoomStart = cid => { const c = X.char(cid) || X.cur(); if (!c) return; G = make(c.id); G.chat.push({ who: 'ta', t: X.v('喂？能听见吗？我被关在另一个房间了。', '你没事吧？我这边门也打不开。', '别慌。我们一起想办法出去。') }); paint(); };\nwindow.gyxRoomSay = async () => {\n    if (!G || busy) return; const el = document.getElementById('gyxRmIn'), t = el && el.value.trim(); if (!t) return; el.value = '';\n    G.chat.push({ who: 'me', t }); busy = true; paint();\n    try { G.chat.push({ who: 'ta', t: await taReply(t) }); } finally { busy = false; } paint();\n};\nwindow.gyxRoomTry = async () => {\n    if (!G) return; const v = (G.dial || [0, 0, 0, 0]).slice(); G.tries++;\n    if (v.join('') === G.code.join('')) {\n        const c = X.char(G.cid), e = { id: 'rm' + Date.now().toString(36), cid: G.cid, at: G.start, end: Date.now(), theme: G.theme.k, ok: true, tries: G.tries, msgs: G.chat.filter(x => x.who === 'me').length };\n        e.line = X.plain(await X.ask(`${X.who(c)}\\n你们刚刚一起逃出了「${G.theme.k}」密室（她试了 ${G.tries} 次密码、跟你说了 ${e.msgs} 句话）。门开了，你们终于见到面。说一句，25 字以内。`) || '') || X.v('出来了！……让我抱一下。', '我就知道我们能出来。', '下次别让我隔着墙听你害怕了。');\n        D.log.unshift(e); D.log = D.log.slice(0, 100); await S.set('d', D); G = null; X.say(c, '🗝️ ' + e.line); window.gyxRoomOpen(c.id, e); return;\n    }\n    G.chat.push({ who: 'sys', t: `🔒 ${v.join('')} —— 不对。${G.tries >= 3 ? '（提示：铜牌上的顺序，就是密码的顺序）' : ''}` }); paint();\n};\nwindow.gyxRoomQuit = async () => { if (!G) return; D.log.unshift({ id: 'rm' + Date.now().toString(36), cid: G.cid, at: G.start, end: Date.now(), theme: G.theme.k, ok: false, tries: G.tries, msgs: G.chat.filter(x => x.who === 'me').length, line: '（放弃了，答案是 ' + G.code.join('') + '）' }); await S.set('d', D); const cid = G.cid; G = null; window.gyxRoomOpen(cid); };\nwindow.gyxRoomDial = (i, v) => { if (G) { G.dial = G.dial || [0, 0, 0, 0]; G.dial[i] = Math.max(0, Math.min(9, +v || 0)); } };\nwindow.gyxRoomLive = () => G; window.gyxRoomData = () => D;\nfunction paint() {\n    if (!G) return; const c = X.char(G.cid);\n    X.panel('gyxRoomOv', G.theme.ico + ' 双人密室 · ' + X.esc(G.theme.k), `<div class=\"gyx-card rm-me\"><b>你在${X.esc(G.theme.mine)}</b><div>📜 ${X.esc(orderNote(G))}</div>${G.mine.map(x => `<div>👁️ ${X.esc(x.t)}</div>`).join('')}<div class=\"gyx-tip\">门上是一把四位数密码锁。另外两样东西在 ${X.esc(X.name(c))} 那边。</div></div>\n      <div class=\"rm-chat\" id=\"gyxRmChat\">${G.chat.map(x => `<div class=\"rm-m ${x.who}\">${x.who === 'ta' ? '<b>' + X.esc(X.name(c)) + '</b>' : ''}${X.esc(x.t)}</div>`).join('')}${busy ? '<div class=\"rm-m ta\">…</div>' : ''}</div>\n      <div class=\"gyx-row\"><input id=\"gyxRmIn\" class=\"gyx-in\" style=\"flex:1\" placeholder=\"隔着墙跟 TA 说话\" onkeydown=\"if(event.key==='Enter'&&!event.isComposing)gyxRoomSay()\"><button class=\"gyx-btn\" onclick=\"gyxRoomSay()\">说</button></div>\n      <div class=\"rm-dial\">${[0, 1, 2, 3].map(i => `<input type=\"number\" min=\"0\" max=\"9\" value=\"${(G.dial || [])[i] || 0}\" oninput=\"gyxRoomDial(${i},this.value)\">`).join('')}<button class=\"gyx-btn\" onclick=\"gyxRoomTry()\">开锁</button></div>\n      <div class=\"gyx-tip\" style=\"text-align:right\"><span style=\"cursor:pointer\" onclick=\"gyxRoomQuit()\">放弃</span></div>`);\n    const ch = document.getElementById('gyxRmChat'); if (ch) ch.scrollTop = ch.scrollHeight;\n}\nwindow.gyxRoomOpen = function (who, win) {\n    const c = X.char(who) || X.cur(); if (!c) return; if (G && G.cid === String(c.id)) return paint(); const cid = String(c.id), H = D.log.filter(x => x.cid === cid);\n    X.panel('gyxRoomOv', '🗝️ 双人密室', `${win ? `<div class=\"gyx-card\"><b>🚪 逃出来了！</b><div>${X.esc(win.line)}</div><div class=\"gyx-tip\">${Math.max(1, Math.round((win.end - win.at) / 60000))} 分钟 · 试了 ${win.tries} 次</div></div>` : ''}\n      <div class=\"gyx-row\">${X.whoSel(cid, 'gyxRoomOpen')}<button class=\"gyx-btn\" onclick=\"gyxRoomStart('${cid}')\">被关起来</button></div>\n      <div class=\"gyx-tip\">${X.v('你们被关在两个房间，各看一半线索。', '只能靠说话。TA 说的话，可不一定准。', '问清楚 TA 那边有什么。')}TA 不会说错数字，但可能漏说、说得含糊。</div>\n      ${H.slice(0, 10).map(x => `<div class=\"sk-h\"><b>${x.ok ? '🚪' : '🔒'}</b><span>${X.esc(x.theme)} · ${new Date(x.at).toLocaleString()} · ${Math.max(1, Math.round((x.end - x.at) / 60000))} 分钟<br>${X.esc(x.line || '')}</span></div>`).join('')}`);\n};\nX.ctx(id => { const x = D.log.find(l => l.cid === String(id)); return x && x.ok && Date.now() - x.end < 6 * 36e5 ? `【刚才你们一起逃出了「${x.theme}」密室】` : ''; }, 'gyxRoom');\nX.action({ key: 'gyx_room', label: '约她玩双人密室（\"要是我们被关在两个房间……\"）', hint: '双人密室', need: c => !D.log.some(x => x.cid === String(c.id) && Date.now() - x.at < 4 * 864e5),\n    run: async c => (await X.reach(c, '你突然想：要是你们被关在两个不同的房间、只能隔着墙说话，能不能一起逃出去？用你的方式约她玩「🗝️ 双人密室」')) ? '约你玩双人密室' : null }, 'gyxRoom');\nX.today(() => ({ title: '🗝️ 双人密室', rows: (G ? [{ t: '进行中', x: X.esc(G.theme.k), go: 'gyxRoomOpen()' }] : []).concat(D.log.filter(x => X.day(new Date(x.at)) === X.day()).map(x => ({ t: x.ok ? '逃出来了' : '放弃了', x: X.esc(x.theme), go: `gyxRoomOpen('${x.cid}')` }))) }), 'gyxRoom');\nX.widget('gyxRoomW', { n: '双人密室', sizes: ['s', 'm'], tap: () => window.gyxRoomOpen(), r: w => X.gw(w, '🗝️', '双人密室', G ? ['被关着…', X.esc(G.theme.k)] : [D.log.length ? '逃出 ' + D.log.filter(x => x.ok).length + ' 次' : '一起被关起来？']) }, 'gyxRoom');\nX.memArr({ k: 'gyxRoom', ico: '🗝️', n: '双人密室', d: '一起逃出过的密室', arr: () => D.log, field: 'line', text: x => x.line || '', meta: x => x.theme + ' · ' + new Date(x.at).toLocaleString(), save: () => S.set('d', D) }, 'gyxRoom');\nX.css('gyxRoomCss', `.rm-me div{font-size:14px;margin:4px 0}.rm-chat{max-height:38vh;overflow:auto;margin:8px 0;display:flex;flex-direction:column;gap:6px}.rm-m{max-width:80%;padding:8px 12px;border-radius:14px;font-size:14px;line-height:1.6}.rm-m.ta{background:#f2f2f4;align-self:flex-start}.rm-m.ta b{display:block;font-size:11px;color:#8e8e93;font-weight:500}.rm-m.me{background:#1d1d1f;color:#fff;align-self:flex-end}.rm-m.sys{align-self:center;font-size:12.5px;color:#ff3b30;background:none}.rm-dial{display:flex;gap:8px;align-items:center;justify-content:center;margin:10px 0}.rm-dial input{width:46px;height:56px;font-size:26px;text-align:center;border-radius:12px;border:2px solid #1d1d1f;font-family:Menlo,monospace}.sk-h{display:flex;gap:10px;padding:8px 0;border-bottom:1px solid #f2f2f4;font-size:13px}.sk-h span{color:#8e8e93}`);\nX.mini({ id: 'gyxRoom', icon: '🗝️', title: '双人密室', desc: '各看一半线索，靠说话逃出去', cat: '一起做', onOpen: () => window.gyxRoomOpen() });\n(() => { const reg = () => { if (typeof registerMiniGame !== 'function') return false; registerMiniGame({ id: 'gyxRoom', name: '双人密室', icon: '🗝️', getStatus: () => null, onResume: () => window.gyxRoomOpen(), onStart: (sid, opp) => window.gyxRoomOpen(String((opp || [])[0] || sid || '')) }); return true; }; if (!reg()) { let n = 0; const iv = setInterval(() => { if (reg() || ++n > 40) clearInterval(iv); }, 500); } })();\n(async () => { D = Object.assign(D, await S.get('d', {})); D.log = D.log || []; })();\n\n//# sourceURL=gyx-plugin/双人密室.js")(X, typeof applyMacros !== 'undefined' ? applyMacros : undefined); } catch (e) { console.error('[插件] 🗝️ 双人密室 出错：', e); }
/* ==== 🃏 命运卡牌 ==== */
try { new Function('X', 'applyMacros', "/* 🃏 命运卡牌：左右滑卡片，替你们俩的日子做决定——感情、钱包、理智、世界四条槽，哪一条见底或者爆满，这一局就结束（感情太满也会窒息）。每种结局收成一张卡，TA 对你的每个选择都有话说 */\nif (window.__gyxFate) return; window.__gyxFate = 1;\nX.feat('gyxFate', { n: '🃏 命运卡牌', desc: '左右滑卡片做决定，四条槽别见底也别爆满' });\nconst S = X.store('fate');\nlet D = { runs: [], ends: {} };   // runs: {id,cid,at,days,end,line}  ends: {key: {at, n}}\nlet R = null, busy = false;   // {cid, m:[4], days, deck:[], card, last}\nconst M = [['💗', '感情'], ['💰', '钱包'], ['🧠', '理智'], ['🌍', '世界']];\nconst ENDS = { '0-0': ['💔 冷掉了', '你们之间的话越来越少，某天发现已经很久没说过晚安。'], '0-1': ['🫠 窒息', '黏得太紧，谁都喘不过气。爱也会把人淹死。'], '1-0': ['🧾 破产', '钱包空了。浪漫交不起房租。'], '1-1': ['💎 金丝笼', '钱多到什么都能买，却买不回一个普通的下午。'], '2-0': ['🌀 崩溃', '你们俩的理智同时断了线。'], '2-1': ['🧊 太清醒', '想得太明白，反而没办法心动了。'], '3-0': ['🏝️ 与世隔绝', '你们关起门来过日子，世界把你们忘了。'], '3-1': ['📸 活在热搜里', '全世界都在看你们，你们却看不见彼此。'] };\nconst BASE = [\n    ['他想养一只猫。', ['算了吧', [0, 5, 0, 0]], ['养！', [10, -10, 5, 0]]], ['老板让你周末加班。', ['拒绝', [5, -10, 5, 0]], ['答应', [-10, 15, -5, 0]]],\n    ['他半夜说睡不着，想跟你打电话。', ['明天再说', [-10, 0, 5, 0]], ['打！', [12, 0, -8, 0]]], ['朋友约你们一起去音乐节。', ['在家好了', [5, 5, 0, -10]], ['去！', [5, -12, 5, 12]]],\n    ['他想把你们的合照发朋友圈。', ['别发', [-5, 0, 0, -8]], ['发吧', [8, 0, 0, 12]]], ['你发现他偷偷记了你喜欢的东西。', ['假装不知道', [8, 0, 0, 0]], ['戳穿他', [5, 0, 5, 0]]],\n    ['一个陌生人在网上骂你们。', ['不理', [0, 0, 8, -5]], ['怼回去', [0, 0, -12, 10]]], ['他说想一起存钱买房。', ['再等等', [-5, 5, 0, 0]], ['开始存', [8, -15, 5, 0]]],\n    ['你们吵架了，他先发了\"在吗\"。', ['晾着', [-15, 0, 5, 0]], ['回他', [10, 0, -3, 0]]], ['有人送你们两张出国旅行的票。', ['卖掉', [-5, 15, 0, 0]], ['去！', [12, -5, 8, 10]]]];\nconst clamp = v => Math.max(0, Math.min(100, v));\nasync function refill() {\n    const c = X.char(R.cid);\n    const o = X.bailu() ? null : X.json(await X.ask(`${X.who(c)}\\n她在玩「命运卡牌」：一张张卡片代表你们日子里会遇到的事，她左滑或右滑做决定。四个数值：感情、钱包、理智、世界（社会关系/外界），都在 0~100，现在是 ${R.m.join(' / ')}，已经过了 ${R.days} 天。\\n写 5 张新卡。卡面是一件具体的小事（可以是你提出的要求、外面发生的事、一个诱惑），左右两个选项，每个选项对四个数值的影响（-20~+20 之间的整数，大多数只动一两个）。要有你的个性；偶尔放一张难选的。\\n只输出 JSON 数组：[{\"t\":\"卡面，25字内\",\"l\":\"左选项，6字内\",\"ld\":[感情,钱包,理智,世界],\"r\":\"右选项，6字内\",\"rd\":[感情,钱包,理智,世界],\"say\":\"你对这件事说的一句话，20字内\"}]`));\n    const arr = Array.isArray(o) ? o.filter(x => x && x.t && Array.isArray(x.ld) && Array.isArray(x.rd)).map(x => ({ t: X.plain(x.t), l: [X.plain(x.l || '不要'), x.ld.slice(0, 4).map(n => +n || 0)], r: [X.plain(x.r || '好'), x.rd.slice(0, 4).map(n => +n || 0)], say: X.plain(x.say || '') })) : [];\n    R.deck.push(...(arr.length ? arr : BASE.slice().sort(() => Math.random() - .5).slice(0, 5).map(b => ({ t: b[0], l: b[1], r: b[2], say: '' }))));\n}\nasync function draw() { if (!R.deck.length) { busy = true; paint(); try { await refill(); } finally { busy = false; } } R.card = R.deck.shift(); paint(); }\nwindow.gyxFateStart = async cid => { const c = X.char(cid) || X.cur(); if (!c) return; R = { cid: String(c.id), m: [50, 50, 50, 50], days: 0, deck: [], at: Date.now() }; await draw(); };\nwindow.gyxFatePick = async side => {\n    if (!R || !R.card || busy) return; const k = R.card[side ? 'r' : 'l']; R.m = R.m.map((v, i) => clamp(v + (k[1][i] || 0))); R.days++;\n    R.last = { t: R.card.t, pick: k[0], say: R.card.say };\n    const bad = R.m.findIndex(v => v <= 0 || v >= 100);\n    if (bad >= 0) {\n        const key = bad + '-' + (R.m[bad] >= 100 ? 1 : 0), E = ENDS[key], c = X.char(R.cid);\n        const line = X.plain(await X.ask(`${X.who(c)}\\n她玩「命运卡牌」，你们一起过了 ${R.days} 天，结局是「${E[0]}」：${E[1]}\\n说一句，20 字以内。`) || '') || X.v('再来一次，这次我们小心点。', '没关系，下一局我陪你。', '……这结局我不认。');\n        D.ends[key] = { at: Date.now(), n: ((D.ends[key] || {}).n || 0) + 1 };\n        D.runs.unshift({ id: 'ft' + Date.now().toString(36), cid: R.cid, at: R.at, days: R.days, end: key, line }); D.runs = D.runs.slice(0, 100); await S.set('d', D);\n        const r = R; R = null; return window.gyxFateOpen(r.cid, { key, days: r.days, line, m: r.m });\n    }\n    await draw();\n};\nfunction paint() {\n    if (!R) return; const c = X.char(R.cid), k = R.card;\n    X.panel('gyxFateOv', '🃏 命运卡牌 · 第 ' + R.days + ' 天', `<div class=\"ft-m\">${M.map((m, i) => `<div><b>${m[0]}</b><i><u style=\"height:${R.m[i]}%\" class=\"${R.m[i] < 20 || R.m[i] > 80 ? 'warn' : ''}\"></u></i><span>${m[1]}</span></div>`).join('')}</div>\n      ${R.last ? `<div class=\"gyx-tip\">上一张：${X.esc(R.last.t)} → <b>${X.esc(R.last.pick)}</b>${R.last.say ? `　${X.esc(X.name(c))}：「${X.esc(R.last.say)}」` : ''}</div>` : ''}\n      ${busy || !k ? `<div class=\"ft-card\"><div class=\"ft-t\">${X.v('洗牌中……', '命运在发牌……')}</div></div>` : `<div class=\"ft-card\" id=\"gyxFtCard\"><div class=\"ft-who\">${X.esc(X.name(c))}</div><div class=\"ft-t\">${X.esc(k.t)}</div></div>\n      <div class=\"ft-btns\"><button class=\"gyx-btn lite\" onclick=\"gyxFatePick(0)\">← ${X.esc(k.l[0])}</button><button class=\"gyx-btn\" onclick=\"gyxFatePick(1)\">${X.esc(k.r[0])} →</button></div><div class=\"gyx-tip\" style=\"text-align:center\">也可以把卡片往左 / 右拖</div>`}`);\n    const el = document.getElementById('gyxFtCard'); if (!el) return; let x0 = null, dx = 0;\n    const dn = e => { x0 = (e.touches ? e.touches[0] : e).clientX; dx = 0; }, mv = e => { if (x0 == null) return; dx = (e.touches ? e.touches[0] : e).clientX - x0; el.style.transform = `translateX(${dx}px) rotate(${dx / 20}deg)`; }, up = () => { window.removeEventListener('pointermove', mv); if (x0 == null) return; x0 = null; if (Math.abs(dx) > 80) gyxFatePick(dx > 0 ? 1 : 0); else el.style.transform = ''; };\n    el.addEventListener('pointerdown', e => { dn(e); window.addEventListener('pointermove', mv); window.addEventListener('pointerup', up, { once: true }); });\n}\nwindow.gyxFateData = () => D; window.gyxFateLive = () => R;\nwindow.gyxFateOpen = function (who, end) {\n    const c = X.char(who) || X.cur(); if (!c) return; if (R && R.cid === String(c.id)) return paint(); const cid = String(c.id), best = D.runs.filter(r => r.cid === cid).reduce((a, r) => Math.max(a, r.days), 0);\n    X.panel('gyxFateOv', '🃏 命运卡牌', `${end ? `<div class=\"gyx-card ft-end\"><b>${ENDS[end.key][0]}</b><div>${ENDS[end.key][1]}</div><div class=\"gyx-tip\">你们一起过了 ${end.days} 天</div><div>${X.esc(X.name(c))}：「${X.esc(end.line)}」</div></div>` : ''}\n      <div class=\"gyx-row\">${X.whoSel(cid, 'gyxFateOpen')}<button class=\"gyx-btn\" onclick=\"gyxFateStart('${cid}')\">${end ? '再来一局' : '开始'}</button></div>\n      <div class=\"gyx-tip\">${X.v('每张卡都是你们日子里的一件事，左滑右滑替你们决定。', '四条槽，别让任何一条见底——也别爆满。', '爱太满也会出事。')}${best ? ' 最长坚持了 ' + best + ' 天。' : ''}</div>\n      <h4 style=\"font-size:14px;margin:12px 0 6px\">结局图鉴（${Object.keys(D.ends).length}/8）</h4><div class=\"ft-ends\">${Object.keys(ENDS).map(k => D.ends[k] ? `<div class=\"on\"><b>${ENDS[k][0]}</b><span>${ENDS[k][1]}</span></div>` : `<div><b>❓</b><span>还没遇到</span></div>`).join('')}</div>`);\n};\nX.ctx(id => { const r = D.runs.find(x => x.cid === String(id)); return r && Date.now() - r.at < 6 * 36e5 ? `【刚才你们玩了命运卡牌】一起过了 ${r.days} 天，结局是「${ENDS[r.end][0]}」。` : ''; }, 'gyxFate');\nX.action({ key: 'gyx_fate', label: '约她玩命运卡牌（看你们能一起撑多少天）', hint: '命运卡牌', need: c => !D.runs.some(x => x.cid === String(c.id) && Date.now() - x.at < 3 * 864e5),\n    run: async c => (await X.reach(c, '你想跟她玩「🃏 命运卡牌」——左滑右滑替你们的日子做决定，看能一起撑多少天。用你的方式约她')) ? '约你玩命运卡牌' : null }, 'gyxFate');\nX.today(() => ({ title: '🃏 命运卡牌', rows: D.runs.filter(r => X.day(new Date(r.at)) === X.day()).slice(0, 3).map(r => ({ t: r.days + ' 天', x: ENDS[r.end][0], go: `gyxFateOpen('${r.cid}')` })) }), 'gyxFate');\nX.widget('gyxFateW', { n: '命运卡牌', sizes: ['s', 'm'], tap: () => window.gyxFateOpen(), r: w => X.gw(w, '🃏', '命运卡牌', R ? ['第 ' + R.days + ' 天', M.map((m, i) => m[0] + R.m[i]).join(' ')] : [Object.keys(D.ends).length + '/8 个结局', D.runs.length ? '最长 ' + D.runs.reduce((a, r) => Math.max(a, r.days), 0) + ' 天' : '']) }, 'gyxFate');\nX.memArr({ k: 'gyxFate', ico: '🃏', n: '命运卡牌', d: '每一局的结局和 TA 说的话', arr: () => D.runs, field: 'line', text: x => x.line || '', meta: x => ENDS[x.end][0] + ' · ' + x.days + ' 天', save: () => S.set('d', D) }, 'gyxFate');\nX.css('gyxFateCss', `.ft-m{display:flex;justify-content:space-around;margin:6px 0 10px}.ft-m div{display:flex;flex-direction:column;align-items:center;gap:3px;font-size:11.5px;color:#8e8e93}.ft-m b{font-size:20px;font-weight:normal}.ft-m i{width:16px;height:60px;border-radius:8px;background:#eee;position:relative;overflow:hidden}.ft-m u{position:absolute;left:0;right:0;bottom:0;background:#1d1d1f;transition:.4s}.ft-m u.warn{background:#ff3b30}\n.ft-card{background:linear-gradient(160deg,#fff8f2,#ffe9ef);border-radius:22px;min-height:200px;padding:22px;box-shadow:0 10px 30px rgba(0,0,0,.1);display:flex;flex-direction:column;justify-content:center;gap:10px;touch-action:pan-y;user-select:none;cursor:grab;transition:transform .15s}.ft-who{font-size:12px;color:#8e8e93}.ft-t{font-size:20px;line-height:1.6;font-weight:600}.ft-btns{display:flex;justify-content:space-between;margin:12px 0}\n.ft-end b{font-size:22px}.ft-ends{display:grid;grid-template-columns:1fr 1fr;gap:8px}.ft-ends div{background:#f7f7f9;border-radius:12px;padding:8px 10px;font-size:12px;color:#aaa}.ft-ends div.on{color:#1d1d1f;background:#fff4e8}.ft-ends b{display:block;font-size:14px}`);\nX.mini({ id: 'gyxFate', icon: '🃏', title: '命运卡牌', desc: '左右滑做决定，四条槽别见底', cat: '一起做', onOpen: () => window.gyxFateOpen() });\n(() => { const reg = () => { if (typeof registerMiniGame !== 'function') return false; registerMiniGame({ id: 'gyxFate', name: '命运卡牌', icon: '🃏', getStatus: () => null, onResume: () => window.gyxFateOpen(), onStart: (sid, opp) => window.gyxFateOpen(String((opp || [])[0] || sid || '')) }); return true; }; if (!reg()) { let n = 0; const iv = setInterval(() => { if (reg() || ++n > 40) clearInterval(iv); }, 500); } })();\n(async () => { D = Object.assign(D, await S.get('d', {})); D.runs = D.runs || []; D.ends = D.ends || {}; })();\n\n//# sourceURL=gyx-plugin/命运卡牌.js")(X, typeof applyMacros !== 'undefined' ? applyMacros : undefined); } catch (e) { console.error('[插件] 🃏 命运卡牌 出错：', e); }
